script:
/* Durar Messenger (مراسلة درر). Paste into a Frappe Custom HTML Block's Script field. */
/* Generated by build_agent_blocks.py from messenger.js. Edit the template, not this copy. */
/* global frappe, root_element */
;(() => {
  "use strict"
  /* Every call goes through the durar_messenger Server Script, which proves the
     employee and signs the request. Messages stream straight from the panel. */
  const METHOD = "durar_messenger"
  // Which copy of this block ERP is running: type DURAR_MESSENGER_VERSION in the browser
  // console. Change it whenever the block changes.
  window.DURAR_MESSENGER_VERSION = "2026-11-14 call video fit v3"
  const host = typeof root_element !== "undefined" ? root_element : null
  if (!host) return
  host.__durarMessengerDestroy?.()
  host.querySelector(".dm")?.remove()
  const ar = (frappe.boot?.lang || document.documentElement.lang || "").startsWith("ar")
  const t = (en, arabic) => (ar ? arabic : en)
  const ME = frappe.session.user

  let me = null,
    limits = { body: 4000, fileBytes: 15 * 1024 * 1024, editMinutes: 15, deleteForAllHours: 48 },
    active = null,
    tab = "chats",
    showArchived = false,
    filter = "",
    searchResults = [],
    replyTo = null,
    editing = null,
    destroyed = false,
    stream = null,
    streamFailures = 0,
    pollTimer = null,
    recorder = null
  const people = new Map()
  const convs = new Map()
  const threads = new Map() // conversationId -> { list, more, loading }
  const typing = new Map() // conversationId -> Map(user -> timeout)
  const timers = new Set()
  const later = (fn, ms) => {
    const id = setTimeout(() => {
      timers.delete(id)
      fn()
    }, ms)
    timers.add(id)
    return id
  }

  const ICONS = {
    plus: '<path d="M12 5v14M5 12h14"/>',
    camera: '<path d="M4 8h3l2-3h6l2 3h3v11H4z"/><circle cx="12" cy="13" r="3.5"/>',
    group: '<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><circle cx="17" cy="9" r="2.5"/><path d="M16 14.2a5 5 0 0 1 5.5 5.8"/>',
    search: '<circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/>',
    back: '<path d="M15 5 8 12l7 7"/>',
    info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5h.01"/>',
    send: '<path d="M4 12 20 4l-6 16-3-7z"/><path d="m11 13 9-9"/>',
    clip: '<path d="m20 11-8.5 8.5a5 5 0 0 1-7-7L13 4a3.5 3.5 0 0 1 5 5l-8.5 8.5a2 2 0 0 1-3-3L14 7"/>',
    mic: '<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/>',
    smile: '<circle cx="12" cy="12" r="9"/><path d="M8.5 14a4 4 0 0 0 7 0M9 9.5h.01M15 9.5h.01"/>',
    x: '<path d="M6 6l12 12M18 6 6 18"/>',
    down: '<path d="m6 9 6 6 6-6"/>',
    check: '<path d="m4 12 5 5L20 6"/>',
    checks: '<path d="m2 12 5 5L18 6"/><path d="m11 16 1 1L23 6"/>',
    clock: '<circle cx="12" cy="12" r="8"/><path d="M12 8v4l2.5 2"/>',
    alert: '<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 16.5h.01"/>',
    file: '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/>',
    download: '<path d="M12 4v11M7 11l5 5 5-5M4 20h16"/>',
    pin: '<path d="M9 4h6l-1 6 4 3v1H6v-1l4-3zM12 14v6"/>',
    mute: '<path d="M11 5 6 9H3v6h3l5 4z"/><path d="m16 9 5 6M21 9l-5 6"/>',
    archive: '<rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v10h14V9M10 13h4"/>',
    play: '<path d="M8 5v14l11-7z"/>',
    pause: '<path d="M8 5h3v14H8zM13 5h3v14h-3z"/>',
    more: '<circle cx="12" cy="5.5" r="1.4"/><circle cx="12" cy="12" r="1.4"/><circle cx="12" cy="18.5" r="1.4"/>',
    trash: '<path d="M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14"/>',
    forward: '<path d="M14 5l7 7-7 7"/><path d="M21 12H9a6 6 0 0 0-6 6v1"/>',
    up: '<path d="m6 15 6-6 6 6"/>',
    translate: '<path d="M4 5h9M8.5 3v2M6 5c0 4 3 7 6 8M11 5c-1 4-4 7-7 8"/><path d="m13 21 4-9 4 9M14.5 18h5"/>',
    phone: '<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>',
    hangup: '<path d="M3 15.5c5-5 13-5 18 0l-2.5 2.5-4-1.5v-3a10 10 0 0 0-5 0v3l-4 1.5z"/>',
    video: '<rect x="3" y="6" width="13" height="12" rx="2"/><path d="m16 10 5-3v10l-5-3"/>',
    videoOff: '<path d="M16 16v1a1 1 0 0 1-1 1H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h2m4 0h4a1 1 0 0 1 1 1v3.5l5-3.5v10"/><path d="m3 3 18 18"/>',
    micOff: '<path d="M9 9v2a3 3 0 0 0 5.1 2.1M15 9.3V6a3 3 0 0 0-5.7-1.3"/><path d="M5 11a7 7 0 0 0 11.5 5.4M19 11a7 7 0 0 1-.4 2.3M12 18v3M3 3l18 18"/>',
    flip: '<path d="M4 8V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v2M20 16v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-2"/><path d="m8 12-3-3-3 3M16 12l3 3 3-3"/>',
    screen: '<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4M12 13V7M9 10l3-3 3 3"/>',
    minimize: '<path d="M4 14h6v6M20 10h-6V4M14 10l7-7M3 21l7-7"/>',
    speaker: '<path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/>',
    bot: '<rect x="4" y="8" width="16" height="12" rx="3"/><path d="M12 8V4M9 14h.01M15 14h.01M2 13v3M22 13v3"/>',
  }
  const svg = (name) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]}</svg>`
  const esc = (s) =>
    String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c])
  /* WhatsApp-style *bold* _italic_ ~strike~ `code` and links, on already-escaped text. */
  function format(text) {
    return esc(text)
      .replace(/`([^`\n]+)`/g, "<code>$1</code>")
      .replace(/(^|[\s(])\*([^*\n]+)\*(?=$|[\s).,!?])/g, "$1<b>$2</b>")
      .replace(/(^|[\s(])_([^_\n]+)_(?=$|[\s).,!?])/g, "$1<i>$2</i>")
      .replace(/(^|[\s(])~([^~\n]+)~(?=$|[\s).,!?])/g, "$1<s>$2</s>")
      .replace(/\bhttps?:\/\/[^\s<]+[^\s<.,;:!?)'"]/g, (url) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`)
      .replace(/\n/g, "<br>")
  }
  const uid = () =>
    (crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(16).slice(2)).replace(/[^A-Za-z0-9]/g, "").slice(0, 32)

  /* fetch instead of frappe.call: a failed typing ping must not open an ERP error dialog. */
  async function api(operation, data = {}) {
    let response, body
    try {
      response = await fetch(`/api/method/${METHOD}`, {
        method: "POST",
        credentials: "same-origin",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
          "X-Frappe-CSRF-Token": frappe.csrf_token,
        },
        body: new URLSearchParams({ operation, data: JSON.stringify(data) }),
      })
      body = await response.json().catch(() => ({}))
    } catch {
      throw Object.assign(new Error(t("No connection. Check your network.", "لا يوجد اتصال. تحقق من الشبكة.")), { status: 0 })
    }
    if (!response.ok || body.exc || body.exc_type) {
      let detail = ""
      try {
        detail = JSON.parse(JSON.parse(body._server_messages || "[]")[0] || "{}").message || ""
      } catch {
        /* no readable message */
      }
      throw Object.assign(
        new Error(String(detail || body.exception || t("Messenger request failed", "تعذر إكمال الطلب")).replace(/<[^>]+>/g, "").slice(0, 300)),
        { status: response.status }
      )
    }
    return body.message
  }

  /* ---------- saved on this computer ----------
     The outgoing queue and drafts live in localStorage, per employee, so a reload, a
     crash or closing the tab never loses a message. The server stays the source of
     truth: everything else is fetched again. */
  const STORE = "durar-messenger:" + ME + ":"
  function readStore(key, fallback) {
    try {
      const value = JSON.parse(localStorage.getItem(STORE + key) || "null")
      return value ?? fallback
    } catch {
      return fallback
    }
  }
  let storageWarned = false
  function writeStore(key, value) {
    try {
      localStorage.setItem(STORE + key, JSON.stringify(value))
    } catch {
      if (!storageWarned) toast(t("This browser's storage is full: unsent messages may not survive a reload.", "مساحة التخزين في المتصفح ممتلئة: قد لا تبقى الرسائل غير المرسلة بعد إعادة التحميل."))
      storageWarned = true
    }
  }
  // Worth retrying by itself: no network, a timeout, the server busy or restarting.
  // Not worth it: the server refused the message (too long, not a member).
  const transient = (error) =>
    [0, 408, 429].includes(Number(error?.status ?? 0)) ||
    Number(error?.status) >= 500 ||
    /unavailable|try again|timed out|no connection|network|connection/i.test(String(error?.message || ""))
  // 1, 2, 4… up to 60 seconds, each 50–100% of that, so tabs don't retry in lockstep.
  const backoff = (attempt) => Math.min(60_000, 1000 * 2 ** Math.min(attempt, 6)) * (0.5 + Math.random() * 0.5)

  /* ---------- @mentions (the same rules as the phone app) ---------- */
  const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  // The "@que" being typed at the cursor: an @ that starts a word, then letters, no newline.
  function mentionQuery(text, cursor) {
    const before = text.slice(0, Math.max(0, Math.min(cursor, text.length)))
    const at = before.lastIndexOf("@")
    if (at < 0) return null
    if (at > 0 && !/\s/.test(before[at - 1])) return null // an email address, not a mention
    const query = before.slice(at + 1)
    if (query.length > 30 || /[\n@]/.test(query)) return null
    return { start: at, query }
  }
  // Names starting with what was typed first, then names containing it.
  function matchPeople(list, query, limit = 6) {
    const q = query.trim().toLowerCase()
    const starts = []
    const contains = []
    for (const p of list) {
      const name = p.name.toLowerCase()
      if (!q || name.startsWith(q) || name.split(/\s+/).some((w) => w.startsWith(q))) starts.push(p)
      else if (name.includes(q)) contains.push(p)
    }
    return [...starts, ...contains].slice(0, limit)
  }
  // Of the people picked while typing, only those still named in the text count.
  function stillMentioned(text, chosen) {
    const users = []
    let all = false
    for (const [user, name] of chosen) {
      if (!new RegExp(`@${escapeRegex(name)}(?![\\p{L}\\p{N}])`, "iu").test(text)) continue
      if (user === "@all") all = true
      else users.push(user)
    }
    return { users, all }
  }
  /* Marks "@Name" for the people a message mentions, in text only (never inside tags). */
  function markMentions(html, m) {
    const names = [...(m.mentions || []).map((u) => person(u).name), ...(m.mentionAll ? ["all"] : [])]
    if (!names.length) return html
    const pattern = new RegExp(`@(?:${names.sort((a, b) => b.length - a.length).map((n) => escapeRegex(esc(n))).join("|")})(?![\\p{L}\\p{N}])`, "giu")
    const mine = new Set([`@${person(ME).name}`.toLowerCase(), ...(m.mentionAll ? ["@all"] : [])])
    return html.replace(/(<[^>]+>)|([^<]+)/g, (all, tag, text) =>
      tag || text.replace(pattern, (hit) => `<span class="dm-mention${mine.has(hit.toLowerCase()) ? " dm-me" : ""}">${hit}</span>`)
    )
  }

  /* ---------- layout ---------- */
  const WELCOME = t(
    "Message and share files with anyone in the company. Pick a chat or a colleague to start.",
    "راسل أي زميل في الشركة وشارك الملفات. اختر محادثة أو زميلاً للبدء."
  )
  // Deleted "for me" in this session; a later edit or reaction must not bring them back.
  const hiddenIds = new Set()
  const root = document.createElement("section")
  root.className = "dm"
  root.dir = ar ? "rtl" : "ltr"
  root.innerHTML = `
    <aside class="dm-side">
      <header class="dm-bar">
        <div class="dm-me"></div>
        <div class="dm-actions">
          <button class="dm-icon" data-act="new-group" title="${t("New group", "مجموعة جديدة")}">${svg("group")}</button>
          <button class="dm-icon" data-act="new-chat" title="${t("New chat", "محادثة جديدة")}">${svg("plus")}</button>
        </div>
      </header>
      <div class="dm-netbar" role="status" hidden></div>
      <label class="dm-search">${svg("search")}<input type="search" placeholder="${t("Search or start a new chat", "ابحث أو ابدأ محادثة جديدة")}" aria-label="${t("Search", "بحث")}"></label>
      <nav class="dm-tabs" role="tablist">
        <button data-tab="chats" role="tab">${t("Chats", "المحادثات")}</button>
        <button data-tab="groups" role="tab">${t("Groups", "المجموعات")}</button>
        <button data-tab="people" role="tab">${t("People", "الموظفون")}</button>
        <button data-tab="calls" role="tab">${t("Calls", "المكالمات")}</button>
      </nav>
      <div class="dm-list" role="list"></div>
    </aside>
    <main class="dm-main">
      <div class="dm-welcome">
        <div class="dm-welcome-art">${svg("group")}</div>
        <h2>${t("Durar Messenger", "مراسلة درر")}</h2>
        <p>${esc(WELCOME)}</p>
      </div>
      <div class="dm-chat" hidden>
        <header class="dm-bar dm-head">
          <button class="dm-icon dm-back" data-act="back" title="${t("Back", "رجوع")}">${svg("back")}</button>
          <button class="dm-head-who" data-act="info"></button>
          <button class="dm-icon dm-call-btn" data-act="call" data-video="1" title="${t("Video call", "مكالمة فيديو")}" hidden>${svg("video")}</button>
          <button class="dm-icon dm-call-btn" data-act="call" data-video="" title="${t("Voice call", "مكالمة صوتية")}" hidden>${svg("phone")}</button>
          <button class="dm-icon" data-act="find" title="${t("Search in chat", "البحث في المحادثة")}">${svg("search")}</button>
          <button class="dm-icon" data-act="info" title="${t("Chat info", "معلومات المحادثة")}">${svg("info")}</button>
        </header>
        <div class="dm-netbar" role="status" hidden></div>
        <button class="dm-callbar" data-act="join-call" hidden></button>
        <button class="dm-pinbar" data-act="pin-bar" hidden></button>
        <div class="dm-find" hidden>
          <input type="search" placeholder="${t("Search this chat", "ابحث في هذه المحادثة")}" aria-label="${t("Search this chat", "ابحث في هذه المحادثة")}">
          <span class="dm-find-count"></span>
          <button class="dm-icon" data-act="find-prev" title="${t("Older match", "النتيجة الأقدم")}">${svg("up")}</button>
          <button class="dm-icon" data-act="find-next" title="${t("Newer match", "النتيجة الأحدث")}">${svg("down")}</button>
          <button class="dm-icon" data-act="find-close" title="${t("Close search", "إغلاق البحث")}">${svg("x")}</button>
        </div>
        <div class="dm-scroll">
          <p class="dm-more" hidden></p>
          <div class="dm-msgs" role="log" aria-live="polite"></div>
        </div>
        <button class="dm-jump" hidden title="${t("Latest messages", "أحدث الرسائل")}">${svg("down")}<span></span></button>
        <div class="dm-mentions" role="listbox" hidden></div>
        <div class="dm-replying" hidden></div>
        <div class="dm-readonly" hidden></div>
        <footer class="dm-compose">
          <button class="dm-icon" data-act="emoji" title="${t("Emoji", "رموز تعبيرية")}">${svg("smile")}</button>
          <button class="dm-icon" data-act="attach" title="${t("Attach", "إرفاق")}">${svg("clip")}</button>
          <input type="file" multiple hidden>
          <div class="dm-recording" hidden><span class="dm-dot"></span><span class="dm-rec-time">0:00</span><button class="dm-icon" data-act="rec-cancel" title="${t("Cancel", "إلغاء")}">${svg("trash")}</button></div>
          <textarea rows="1" placeholder="${t("Type a message", "اكتب رسالة")}" aria-label="${t("Message", "رسالة")}"></textarea>
          <button class="dm-icon dm-send" data-act="send" title="${t("Send", "إرسال")}">${svg("mic")}</button>
        </footer>
      </div>
    </main>
    <div class="dm-drawer" hidden></div>
    <div class="dm-pop" hidden></div>
    <div class="dm-viewer" hidden role="dialog" aria-modal="true">
      <header><button class="dm-viewer-back" data-act="close-viewer">${svg("back")}<span>${t("Back", "رجوع")}</span></button>
        <span class="dm-viewer-name"></span><a class="dm-icon dm-viewer-save" target="_blank" rel="noopener" title="${t("Download", "تنزيل")}">${svg("download")}</a></header>
      <div class="dm-viewer-stage"></div>
    </div>
    <div class="dm-toast" role="status" hidden></div>`
  host.appendChild(root)
  const $ = (sel) => root.querySelector(sel)
  const list = $(".dm-list"),
    chat = $(".dm-chat"),
    scroller = $(".dm-scroll"),
    msgsEl = $(".dm-msgs"),
    input = $("textarea"),
    fileInput = $('input[type="file"]'),
    drawer = $(".dm-drawer"),
    pop = $(".dm-pop"),
    sendBtn = $(".dm-send"),
    searchInput = $(".dm-search input"),
    viewer = $(".dm-viewer"),
    findBar = $(".dm-find")

  function theme() {
    const desk = document.documentElement.getAttribute("data-theme")
    root.dataset.theme = desk === "dark" ? "dark" : "light"
    window.__durarCallUI?.setTheme(root.dataset.theme)
  }
  theme()
  const themeWatch = new MutationObserver(theme)
  themeWatch.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] })
  const sizeWatch = new ResizeObserver(() => root.classList.toggle("dm-narrow", root.clientWidth < 760))
  sizeWatch.observe(root)

  let toastTimer
  function toast(text) {
    const el = $(".dm-toast")
    el.textContent = text
    el.hidden = false
    clearTimeout(toastTimer)
    toastTimer = setTimeout(() => (el.hidden = true), 4000)
  }
  const fail = (error) => toast(error?.message || String(error))

  /* ---------- people, time and labels ---------- */
  /* The CEO assistant's own chat with the CEO, where it reports on coordination. */
  const ASSISTANT = "durar-assistant"
  const person = (user) =>
    user === ASSISTANT
      ? { user, name: t("Durar Assistant", "مساعد درر"), designation: t("CEO assistant", "مساعد الرئيس التنفيذي") }
      : people.get(user) || { user, name: user.split("@")[0] }
  const nameOf = (user) => (user === ME ? t("You", "أنت") : person(user).name)
  const initials = (name) =>
    String(name || "?").trim().split(/\s+/).slice(0, 2).map((w) => w[0]).join("").toUpperCase()
  const hue = (s) => [...String(s)].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 7)
  function avatar(user, size = "", group = null) {
    if (group) {
      // The group's own picture, when it has one, covers the default icon.
      const img = group.image ? `<img src="${esc(group.image)}" alt="" loading="lazy" onerror="this.remove()">` : ""
      return `<span class="dm-av ${size}" style="--h:${hue(group.id)}">${svg("group")}${img}</span>`
    }
    if (user === ASSISTANT) return `<span class="dm-av dm-bot ${size}">${svg("bot")}</span>`
    const p = person(user)
    const img = p.image ? `<img src="${esc(p.image)}" alt="" loading="lazy" onerror="this.remove()">` : ""
    return `<span class="dm-av ${size}" style="--h:${hue(user)}"><b>${esc(initials(p.name))}</b>${img}</span>`
  }
  const online = (user) => {
    const seen = person(user).lastSeenAt
    return seen && Date.now() - new Date(seen).getTime() < 70_000
  }
  const locale = ar ? "ar" : undefined
  const time = (at) => new Date(at).toLocaleTimeString(locale, { hour: "numeric", minute: "2-digit" })
  function dayLabel(at) {
    const d = new Date(at),
      today = new Date()
    const days = Math.round((new Date(today.toDateString()) - new Date(d.toDateString())) / 86_400_000)
    if (days === 0) return t("Today", "اليوم")
    if (days === 1) return t("Yesterday", "أمس")
    if (days < 7) return d.toLocaleDateString(locale, { weekday: "long" })
    return d.toLocaleDateString(locale, { day: "numeric", month: "short", year: "numeric" })
  }
  function listTime(at) {
    const d = new Date(at)
    return new Date().toDateString() === d.toDateString() ? time(at) : dayLabel(at)
  }
  function lastSeen(user) {
    if (online(user)) return t("online", "متصل الآن")
    const seen = person(user).lastSeenAt
    if (!seen) return person(user).designation || person(user).department || ""
    return t("last seen ", "آخر ظهور ") + `${dayLabel(seen)} ${time(seen)}`
  }
  const convTitle = (c) => (c.kind === "group" ? c.title : c.peer ? person(c.peer).name : t("You (notes)", "أنت (ملاحظات)"))
  const muted = (c) => c.mutedUntil && new Date(c.mutedUntil) > new Date()
  const size = (n) => (n < 1024 ? `${n} B` : n < 1048576 ? `${(n / 1024).toFixed(0)} KB` : `${(n / 1048576).toFixed(1)} MB`)

  function callEntry(m) {
    try {
      const e = JSON.parse(m.body)
