    const th = active && thread(active)
    if (!th || th.loading) return
    if (th.more && scroller.scrollTop < 600) loadMessages(active, "older")
    else if (th.newer && scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 600) loadMessages(active, "newer")
    if (nearBottom() && !th.newer) readActive()
  })

  /* Every switch bumps this, so a slow "open" that finishes after the employee has
     moved on never takes the screen back. */
  let openSeq = 0
  function closeChat() {
    closeFind()
    stopRecording() // a voice note in progress goes to the chat it was recorded in
    if (editing) cancelEdit()
    saveDraft()
    openSeq += 1
    active = null
    replyTo = null
    closeMentions()
    renderReply()
    input.value = ""
    chat.dataset.conv = ""
    root.classList.remove("dm-chatting")
    chat.hidden = true
    $(".dm-welcome").hidden = false
    renderList()
  }
  async function open(id) {
    const c = convs.get(id)
    if (!c) return
    if (id !== active) {
      stopRecording()
      closeFind()
    }
    if (editing) cancelEdit()
    saveDraft()
    openSeq += 1
    active = id
    replyTo = null
    chosen.clear()
    closeMentions()
    pinIndex = 0
    renderReply()
    // The composer sends only to the chat it was opened for (see submit).
    chat.dataset.conv = id
    root.classList.add("dm-chatting")
    $(".dm-welcome").hidden = true
    chat.hidden = false
    c.unreadMarker = null
    const th = thread(id)
    renderHead()
    renderList()
    renderMessages({ stick: true })
    input.value = drafts.get(id) || ""
    resize()
    if (!root.classList.contains("dm-narrow")) input.focus()
    if (!th.loaded || th.stale || th.newer) await loadMessages(id)
    readActive(true)
    renderPinBar()
    loadPins(id)
    if (c.kind === "direct" && c.peer) refreshPresence([c.peer])
  }
  /* mode: "latest" (the live end), "older" or "newer" (the next page from the loaded
     edge), or { around: messageId } (a window in the middle of the history, for search
     results and quotes; the thread then is not at the live end until scrolled down). */
  async function loadMessages(id, mode = "latest") {
    const th = thread(id)
    if (th.loading) return
    th.loading = true
    const settled = th.list.filter((m) => !m.pending && !m.failed)
    const edge = mode === "older" ? settled[0] : mode === "newer" ? settled[settled.length - 1] : null
    const cursor = edge && { at: edge.cursor || new Date(edge.createdAt).toISOString(), id: edge.id }
    try {
      const result = await api("messages.list", {
        conversationId: id,
        ...(mode === "older" && cursor ? { before: cursor } : {}),
        ...(mode === "newer" && cursor ? { after: cursor } : {}),
        ...(mode.around ? { around: mode.around } : {}),
      })
      for (const [user, p] of Object.entries(result.people || {})) if (!people.has(user) || !people.get(user).employee) people.set(user, { ...people.get(user), ...p })
      const conv = result.conversation
      if (conv) mergeConv(conv)
      if (mode === "older" || mode === "newer") {
        result.messages.forEach(upsert)
        if (mode === "older") th.more = result.more
        else th.newer = result.newer
      } else {
        const pending = mode === "latest" ? th.list.filter((m) => m.pending || m.failed) : []
        th.list = result.messages
        pending.forEach(upsert)
        th.more = result.more
        th.newer = !!result.newer
        const c = convs.get(id)
        if (mode === "latest" && c && c.unread) {
          const firstUnread = result.messages.filter((m) => m.sender !== ME && m.kind !== "system").slice(-c.unread)[0]
          c.unreadMarker = firstUnread?.id || null
        }
      }
      th.loaded = true
      th.stale = false
      if (active === id) renderMessages(mode === "older" ? { keep: "top" } : mode === "latest" ? { stick: true } : {})
      return true
    } catch (error) {
      fail(error)
      return false
    } finally {
      th.loading = false
    }
  }
  /* ---------- photo and video viewer ---------- */
  function view(m) {
    const f = m.file
    if (!f?.url) return
    const stage = viewer.querySelector(".dm-viewer-stage")
    stage.innerHTML = /^video\//.test(f.mime || "")
      ? `<video src="${esc(f.url)}" controls autoplay playsinline></video>`
      : `<img src="${esc(f.url)}" alt="${esc(f.name)}">`
    viewer.querySelector(".dm-viewer-name").innerHTML = `<b>${esc(nameOf(m.sender))}</b><small>${esc(f.name)} · ${esc(time(m.createdAt))}</small>`
    viewer.querySelector(".dm-viewer-save").href = f.url + "&download=1"
    viewer.hidden = false
    viewer.querySelector(".dm-viewer-back").focus()
  }
  function closeViewer() {
    viewer.hidden = true
    viewer.querySelector(".dm-viewer-stage").innerHTML = "" // stops a playing video
  }
  viewer.querySelector(".dm-viewer-stage").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) closeViewer()
  })

  /* ---------- search in the open chat (whole history, on the server) ---------- */
  const find = { query: "", results: [], index: -1, seq: 0 }
  const findInput = findBar.querySelector("input")
  function openFind() {
    findBar.hidden = false
    findInput.focus()
    findInput.select()
  }
  function closeFind() {
    if (findBar.hidden && !find.query) return
    findBar.hidden = true
    findInput.value = ""
    Object.assign(find, { query: "", results: [], index: -1, seq: find.seq + 1 })
    findBar.querySelector(".dm-find-count").textContent = ""
    if (active) renderMessages()
  }
  function showFindCount() {
    findBar.querySelector(".dm-find-count").textContent = !find.query
      ? ""
      : find.results.length
        ? `${find.index + 1} / ${find.results.length}`
        : t("No results", "لا نتائج")
  }
  /* Results are newest first: "up" goes to an older match, "down" to a newer one. */
  function stepFind(direction) {
    if (!find.results.length) return
    find.index = Math.min(find.results.length - 1, Math.max(0, find.index + direction))
    showFindCount()
    jumpTo(find.results[find.index].id)
  }
  let findTimer
  findInput.addEventListener("input", () => {
    clearTimeout(findTimer)
    const q = findInput.value.trim()
    const seq = ++find.seq
    if (q.length < 2) {
      Object.assign(find, { query: "", results: [], index: -1 })
      showFindCount()
      return active && renderMessages()
    }
    findTimer = setTimeout(async () => {
      const conversationId = active
      try {
        const { results } = await api("messages.find", { conversationId, query: q })
        if (seq !== find.seq || active !== conversationId) return
        Object.assign(find, { query: q, results, index: results.length ? 0 : -1 })
        showFindCount()
        renderMessages()
        if (results.length) jumpTo(results[0].id)
      } catch (error) {
        fail(error)
      }
    }, 350)
  })
  findInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault()
      stepFind(e.shiftKey ? -1 : 1)
    }
  })

  /* ---------- forward ---------- */
  let forwarding = null
  const forwardPicks = new Set() // "c:<conversationId>" or "p:<user>"
  function forwardPicker(m) {
    forwarding = m
    forwardPicks.clear()
    drawer.dataset.view = "forward"
    drawerShell(
      t("Forward message to", "إعادة توجيه الرسالة إلى"),
      `<label class="dm-search">${svg("search")}<input type="search" data-role="forward-filter" placeholder="${t("Search chats and employees", "ابحث في المحادثات والموظفين")}"></label>
      <div class="dm-picks"></div>
      <button class="dm-primary" data-act="forward-send">${svg("send")} ${t("Send", "إرسال")}</button>`
    )
    renderForward()
    drawer.querySelector('[data-role="forward-filter"]').focus()
  }
  function renderForward() {
    const q = (drawer.querySelector('[data-role="forward-filter"]')?.value || "").toLowerCase()
    const chats = sortedConvs().filter((c) => !c.left && !(c.onlyAdminsSend && c.role !== "admin") && convTitle(c).toLowerCase().includes(q))
    const withChat = new Set(chats.map((c) => c.peer).filter(Boolean))
    const others = [...people.values()]
      .filter((p) => p.employee && p.user !== ME && !withChat.has(p.user) && `${p.name} ${p.department || ""}`.toLowerCase().includes(q))
      .sort((a, b) => a.name.localeCompare(b.name))
      .slice(0, 100)
    const row = (key, pic, label, sub) =>
      `<button class="dm-row${forwardPicks.has(key) ? " dm-on" : ""}" data-act="forward-pick" data-key="${esc(key)}">${pic}
        <span class="dm-row-main"><span class="dm-row-top"><b>${esc(label)}</b></span><span class="dm-row-sub"><span class="dm-preview">${esc(sub)}</span></span></span>
        <span class="dm-check">${forwardPicks.has(key) ? svg("check") : ""}</span></button>`
    drawer.querySelector(".dm-picks").innerHTML =
      (chats.length ? `<h4 class="dm-section">${t("Recent chats", "المحادثات الأخيرة")}</h4>` : "") +
      chats.slice(0, 50).map((c) => row("c:" + c.id, c.kind === "group" ? avatar(null, "", c) : avatar(c.peer || ME), convTitle(c), c.kind === "group" ? `${c.memberCount} ${t("members", "عضو")}` : "")).join("") +
      (others.length ? `<h4 class="dm-section">${t("Other employees", "موظفون آخرون")}</h4>` : "") +
      others.map((p) => row("p:" + p.user, avatar(p.user), p.name, [p.designation, p.department].filter(Boolean).join(" · "))).join("")
    drawer.querySelector(".dm-primary").textContent = forwardPicks.size
      ? t(`Send to ${forwardPicks.size}`, `إرسال إلى ${forwardPicks.size}`)
      : t("Send", "إرسال")
  }
  async function forwardSend() {
    const m = forwarding
    if (!m || !forwardPicks.size) return toast(t("Choose who to forward to.", "اختر من ستعيد التوجيه إليه."))
    const picks = [...forwardPicks]
    closeDrawer()
    let sent = 0
    for (const key of picks) {
      try {
        let conversationId = key.slice(2)
        if (key.startsWith("p:")) {
          const { conversation } = await api("conversations.direct", { user: key.slice(2) })
          mergeConv(conversation)
          conversationId = conversation.id
        }
        const { message } = await api("messages.send", { conversationId, clientId: uid(), forwardOf: m.id })
        onMessage(message, true)
        sent++
      } catch (error) {
        fail(error)
      }
    }
    renderList()
    if (sent) toast(sent === 1 ? t("Message forwarded", "تمت إعادة توجيه الرسالة") : t(`Forwarded to ${sent} chats`, `أُعيد توجيهها إلى ${sent} محادثات`))
  }
  drawer.addEventListener("input", (e) => {
    if (e.target.dataset.role === "forward-filter") renderForward()
  })

  /* ---------- translate ---------- */
  async function translateMessage(m, lang) {
    if (!m) return
    const conversationId = m.conversationId
    try {
      if (lang) toast(t("Translating…", "جارٍ الترجمة…"))
      const { translation } = await api("messages.translate", { messageId: m.id, lang })
      // Kept on the server too, so the message stays translated after a reload.
      const current = thread(conversationId).list.find((x) => x.id === m.id)
      if (current) upsert({ ...current, translation })
      if (active === conversationId) renderMessages()
    } catch (error) {
      fail(error)
    }
  }

  /* Shows one message, loading the part of the history around it when it isn't loaded. */
  async function jumpTo(id) {
    const conversationId = active
    if (!thread(conversationId).list.some((m) => m.id === id) && !(await loadMessages(conversationId, { around: id }))) return
    if (active !== conversationId) return
    const target = msgsEl.querySelector(`[data-id="${CSS.escape(id)}"]`)
    if (!target) return
    target.scrollIntoView({ block: "center" })
    target.classList.add("dm-flash")
    later(() => target.classList.remove("dm-flash"), 1600)
  }

  let readTimer = null
  function readActive(force = false) {
    const c = convs.get(active)
    if (!c || document.hidden || (!force && !c.unread) || !nearBottom() || thread(c.id).newer) return
    c.unread = 0
    c.mentioned = false
    renderList()
    updateJump()
    if (readTimer) return
    readTimer = later(() => {
      readTimer = null
      api("messages.read", { conversationId: c.id }).catch(() => {})
    }, 400)
  }
  document.addEventListener("visibilitychange", onVisible)
  function onVisible() {
    if (document.hidden) return
    readActive()
    kickQueue() // back from sleep or another app
  }

  function mergeConv(c) {
    const old = convs.get(c.id)
    convs.set(c.id, { ...old, ...c, unreadMarker: old?.unreadMarker })
  }
  async function refreshConv(id) {
    try {
      const { conversation } = await api("conversations.get", { conversationId: id })
      mergeConv(conversation)
      memberCache.delete(id) // membership may have changed
      if (active === id) {
        loadPins(id)
        renderHead()
        renderMessages()
      }
      renderList()
      if (drawer.dataset.view === "info" && drawer.dataset.id === id) showInfo(id)
    } catch {
      /* the next list refresh catches up */
    }
  }

  /* ---------- pinned messages ---------- */
  const pins = new Map() // conversationId -> pinned messages, latest first
  let pinIndex = 0
  const pinsOf = (id) => pins.get(id) || []
  const pinPreview = (m) =>
    m.kind === "voice" ? t("🎤 Voice message", "🎤 رسالة صوتية") : m.kind === "image" ? `📷 ${m.body || t("Photo", "صورة")}` : m.kind === "file" ? `📄 ${m.file?.name || t("File", "ملف")}` : String(m.body || "").replace(/\s+/g, " ")
  function renderPinBar() {
    const bar = $(".dm-pinbar")
    const list = pinsOf(active)
    bar.hidden = !list.length
    if (!list.length) return
    const shown = list[pinIndex % list.length]
    bar.innerHTML = `${svg("pin")}<span><b>${esc(t("Pinned message", "رسالة مثبتة"))}${list.length > 1 ? ` · ${(pinIndex % list.length) + 1} ${t("of", "من")} ${list.length}` : ""}</b><small>${esc(pinPreview(shown))}</small></span>`
  }
  async function loadPins(id) {
    try {
      pins.set(id, (await api("messages.pins", { conversationId: id })).pins)
      if (active === id) renderPinBar()
    } catch {
      /* the last list stays */
    }
  }
  async function setPinned(m, pinned) {
    try {
      pins.set(m.conversationId, (await api("messages.pin", { messageId: m.id, pinned })).pins)
      if (active === m.conversationId) renderPinBar()
    } catch (error) {
      fail(error)
    }
  }
  // A pinned message that was edited or deleted updates in the list.
  function refreshPinned(m) {
    const list = pinsOf(m.conversationId)
    if (!list.some((p) => p.id === m.id)) return
    pins.set(m.conversationId, m.deleted ? list.filter((p) => p.id !== m.id) : list.map((p) => (p.id === m.id ? { ...p, ...m } : p)))
    if (active === m.conversationId) renderPinBar()
  }

  /* ---------- @mention picker ---------- */
  const chosen = new Map() // user -> the name as inserted
  const memberCache = new Map() // conversationId -> usernames
  let mentionState = null // { start, items, index }
  async function membersOf(id) {
    if (memberCache.has(id)) return memberCache.get(id)
    const result = await api("conversations.members", { conversationId: id })
    for (const [user, p] of Object.entries(result.people || {})) if (!people.get(user)?.employee) people.set(user, { ...people.get(user), ...p })
    const ids = result.members.map((x) => x.user)
    memberCache.set(id, ids)
    return ids
  }
  function closeMentions() {
    mentionState = null
    const box = $(".dm-mentions")
    box.hidden = true
    box.innerHTML = ""
  }
  function renderMentions() {
    const box = $(".dm-mentions")
    box.hidden = false
    box.innerHTML = mentionState.items
      .map(
        (item, i) =>
          `<button type="button" role="option" data-act="pick-mention" data-i="${i}" class="${i === mentionState.index ? "dm-on" : ""}">${item.all ? `<span class="dm-av dm-add">${svg("group")}</span>` : avatar(item.user)}<span>${item.all ? esc(t("all · notify everyone", "الجميع · تنبيه الكل")) : esc(item.name)}</span></button>`
      )
      .join("")
  }
  async function updateMentions() {
    const c = convs.get(active)
    const q = c && c.kind === "group" && !c.left ? mentionQuery(input.value, input.selectionStart) : null
    if (!q) return closeMentions()
    let ids
    try {
      ids = await membersOf(active)
    } catch {
      return closeMentions()
    }
    const now = mentionQuery(input.value, input.selectionStart) // typing went on while the list loaded
    if (!now || now.start !== q.start) return
    const list = ids.filter((u) => u !== ME).map((user) => ({ user, name: person(user).name }))
    const items = [...(c.role === "admin" && "all".startsWith(now.query.toLowerCase()) ? [{ user: "@all", name: "all", all: true }] : []), ...matchPeople(list, now.query)].slice(0, 6)
    if (!items.length) return closeMentions()
    mentionState = { start: q.start, items, index: 0 }
    renderMentions()
  }
  function pickMention(i) {
    const item = mentionState?.items[i]
    if (!item) return
    const text = `@${item.name} `
    input.value = input.value.slice(0, mentionState.start) + text + input.value.slice(input.selectionStart)
    const at = mentionState.start + text.length
    input.setSelectionRange(at, at)
    chosen.set(item.user, item.name)
    closeMentions()
    saveDraft()
    resize()
    input.focus()
  }

  /* ---------- composer ---------- */
  const drafts = new Map(Object.entries(readStore("drafts", {})).filter(([, text]) => typeof text === "string" && text))
  let draftTimer = null
  function persistDrafts() {
    clearTimeout(draftTimer)
    draftTimer = setTimeout(() => writeStore("drafts", Object.fromEntries([...drafts].filter(([, text]) => text.trim()))), 400)
  }
  for (const name of ["set", "delete"]) {
    const original = drafts[name].bind(drafts)
    drafts[name] = (...args) => {
      const result = original(...args)
      persistDrafts()
      return result
    }
  }
  function saveDraft() {
    if (active && !editing) drafts.set(active, input.value)
  }
  function resize() {
    input.style.height = "auto"
    input.style.height = Math.min(input.scrollHeight, 140) + "px"
    sendBtn.innerHTML = svg(input.value.trim() || editing ? "send" : "mic")
    sendBtn.title = input.value.trim() || editing ? t("Send", "إرسال") : t("Record voice message", "تسجيل رسالة صوتية")
  }
  let lastTyping = 0
  input.addEventListener("input", () => {
    resize()
    saveDraft() // kept as you type, so a reload restores it
    updateMentions()
    if (active && input.value.trim() && Date.now() - lastTyping > 3000) {
      lastTyping = Date.now()
      api("typing", { conversationId: active }).catch(() => {})
    }
  })
  input.addEventListener("click", updateMentions)
  input.addEventListener("keyup", (e) => {
    if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) updateMentions()
  })
  input.addEventListener("keydown", (e) => {
    if (mentionState && !e.isComposing) {
      const n = mentionState.items.length
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault()
        mentionState.index = (mentionState.index + (e.key === "ArrowDown" ? 1 : n - 1)) % n
        return renderMentions()
      }
      if (e.key === "Enter" || e.key === "Tab") {
        e.preventDefault()
        return pickMention(mentionState.index)
      }
      if (e.key === "Escape") {
        e.preventDefault()
        e.stopPropagation()
        return closeMentions()
      }
    }
    if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
      e.preventDefault()
      submit()
    } else if (e.key === "Escape" && (editing || replyTo)) {
      // Esc first drops the reply or edit; the next Esc goes back to the chat list.
      e.stopPropagation()
      if (editing) cancelEdit()
      else {
        replyTo = null
        renderReply()
      }
    } else if (e.key === "ArrowUp" && !input.value) {
      const own = [...thread(active).list].reverse().find((m) => m.sender === ME && m.kind === "text" && !m.deleted && !m.pending)
      if (own && canEdit(own)) {
        e.preventDefault()
        startEdit(own)
      }
    }
  })
  input.addEventListener("paste", (e) => {
    const files = [...(e.clipboardData?.files || [])]
    if (files.length) {
      e.preventDefault()
      sendFiles(files)
    }
  })
  function renderReply() {
    const el = $(".dm-replying")
    const target = editing || replyTo
    el.hidden = !target
    if (!target) return
    el.innerHTML = `<div><b>${editing ? t("Edit message", "تعديل الرسالة") : esc(nameOf(target.sender))}</b><span>${esc(target.body || target.file?.name || t("Attachment", "مرفق"))}</span></div>
      <button class="dm-icon" data-act="cancel-reply" title="${t("Cancel", "إلغاء")}">${svg("x")}</button>`
  }
  const canEdit = (m) => m.sender === ME && m.kind === "text" && !m.deleted && Date.now() - new Date(m.createdAt) < limits.editMinutes * 60_000
  function startEdit(m) {
    editing = m
    replyTo = null
    chosen.clear()
    for (const user of m.mentions || []) chosen.set(user, person(user).name)
    input.value = m.body
    renderReply()
    resize()
    input.focus()
  }
  function cancelEdit() {
    editing = null
    chosen.clear()
    input.value = drafts.get(active) || ""
    renderReply()
    resize()
  }
  async function submit() {
    // Never send to a chat other than the one on screen, even mid-switch.
    const target = active
    if (!target || chat.hidden || chat.dataset.conv !== target || !convs.has(target)) return
    const body = input.value.replace(/\s+$/, "")
    if (editing) {
      const original = editing
      if (!body.trim() || body === original.body) return cancelEdit()
      editing = null
      input.value = ""
      drafts.delete(target)
      renderReply()
      resize()
      upsert({ ...original, body, editedAt: new Date().toISOString() })
      renderMessages()
      const mentioned = stillMentioned(body, chosen)
      chosen.clear()
      return api("messages.edit", { messageId: original.id, body, mentions: mentioned.users }).catch((error) => {
        fail(error)
        loadMessages(original.conversationId)
      })
    }
    if (!body.trim()) return toggleRecording()
    if (body.length > limits.body) return toast(t(`Messages can be up to ${limits.body} characters.`, `يمكن أن تصل الرسالة إلى ${limits.body} حرف.`))
    askNotifications()
    const mention = stillMentioned(body, chosen)
    chosen.clear()
    closeMentions()
    input.value = ""
    drafts.delete(target)
    resize()
    const reply = replyTo
    replyTo = null
    renderReply()
    await sendMessage(
      { conversationId: target, body, replyTo: reply?.id, ...(mention.users.length ? { mentions: mention.users } : {}), ...(mention.all ? { mentionAll: true } : {}) },
      { reply }
    )
  }
  /* Sending: the message shows at once and is saved in the queue before any network
     attempt. The queue sends in order with the same clientId on every attempt; the
     server answers a repeat with the original message, so a lost reply never makes a
     duplicate. Only a refusal from the server marks it failed. Tabs share the queue;
     a browser lock lets one tab at a time send it. */
