  /* Big photos are re-encoded before upload, the way WhatsApp sends "standard quality". */
  async function shrink(file) {
    if (!/^image\/(jpeg|png|webp)$/.test(file.type) || file.size < 400_000) return file
    try {
      const bitmap = await createImageBitmap(file)
      const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height))
      const canvas = document.createElement("canvas")
      canvas.width = Math.round(bitmap.width * scale)
      canvas.height = Math.round(bitmap.height * scale)
      canvas.getContext("2d").drawImage(bitmap, 0, 0, canvas.width, canvas.height)
      const blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/jpeg", 0.85))
      return blob && blob.size < file.size ? new File([blob], file.name.replace(/\.\w+$/, "") + ".jpg", { type: "image/jpeg" }) : file
    } catch {
      return file
    }
  }
  /* Files up to 2 MB go in one request. Bigger ones go in 4 MB chunks, each starting where
     the server stopped, so a dropped connection costs only the last chunk and the upload
     picks up again by itself. The whole file's SHA-256 is checked by the server at the
     end, and each chunk's as it arrives. */
  const CHUNK = 4 * 1048576
  const SINGLE_REQUEST = 2 * 1048576
  const uploadSessions = new Map() // clientId -> { id }: where to resume
  const preparedFiles = new Map() // clientId -> the exact file being uploaded
  const uploadPct = new Map() // clientId -> 0..100 while uploading
  async function sha256Hex(blob) {
    if (!window.crypto?.subtle) return null
    const digest = await crypto.subtle.digest("SHA-256", await blob.arrayBuffer())
    return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("")
  }
  // Frees an unfinished upload on the server (it would otherwise wait 15 idle minutes).
  async function abandonUpload(conversationId, session) {
    const id = session?.id
    if (!id) return
    session.id = null
    try {
      const { url } = await api("files.ticket", { conversationId })
      await fetch(`${url}&upload=${id}`, { method: "DELETE", mode: "cors", credentials: "omit" })
    } catch {
      /* the server frees it by itself */
    }
  }
  async function upload(conversationId, file, session = {}, onProgress = () => {}) {
    const ticket = await api("files.ticket", { conversationId })
    if (file.size > ticket.maxBytes) throw new Error(tooBig(file.name))
    if (file.size > SINGLE_REQUEST) return resumableUpload(conversationId, ticket.url, file, session, onProgress)
    let response
    try {
      response = await fetch(ticket.url, {
        method: "POST",
        mode: "cors",
        credentials: "omit",
        headers: { "Content-Type": file.type || "application/octet-stream", "X-File-Name": encodeURIComponent(file.name || "file") },
        body: file,
      })
    } catch {
      throw Object.assign(new Error(t("Upload failed. Check your network.", "فشل الرفع. تحقق من الشبكة.")), { status: 0 })
    }
    const body = await response.json().catch(() => ({}))
    if (!response.ok) throw Object.assign(new Error(body.error || t("Upload failed.", "فشل الرفع.")), { status: response.status })
    return body.file
  }
  async function resumableUpload(conversationId, firstUrl, file, session, onProgress) {
    let url = firstUrl
    const offline = () => Object.assign(new Error(t("Upload failed. Check your network.", "فشل الرفع. تحقق من الشبكة.")), { status: 0 })
    async function call(method, id, headers, body) {
      const send = () => fetch(id ? `${url}&upload=${id}` : url, { method, mode: "cors", credentials: "omit", headers, body })
      let response
      try {
        response = await send()
      } catch {
        throw offline()
      }
      if (response.status === 401) {
        // The ticket lasts a few minutes; a long upload asks for a fresh one.
        url = (await api("files.ticket", { conversationId })).url
        try {
          response = await send()
        } catch {
          throw offline()
        }
      }
      const data = await response.json().catch(() => ({}))
      if (!response.ok) throw Object.assign(new Error(data.error || t("Upload failed.", "فشل الرفع.")), { status: response.status, offset: data.offset })
      return data
    }
    const status = (id) => call("GET", id, {})
    const wait = (ms) => new Promise((resolve) => later(resolve, ms))
    async function begin() {
      const sha = await sha256Hex(file)
      const created = await call("POST", null, {
        "X-Upload-Length": String(file.size),
        "X-File-Name": encodeURIComponent(file.name || "file"),
        "Content-Type": file.type || "application/octet-stream",
        ...(sha ? { "X-Upload-Sha256": sha } : {}),
      })
      session.id = created.id
      return { offset: 0, size: file.size }
    }
    // Where did the earlier attempt stop? A forgotten upload starts over.
    let state = null
    if (session.id) {
      try {
        state = await status(session.id)
      } catch (error) {
        if (error.status !== 404) throw error
        session.id = null
      }
    }
    if (!session.id) state = await begin()
    onProgress(Math.round((state.offset / file.size) * 100))
    let tries = 0
    let polls = 0
    let restarts = 0
    for (;;) {
      if (session.cancelled) throw Object.assign(new Error(t("Upload cancelled.", "تم إلغاء الرفع.")), { status: -1 })
      if (state.file) return state.file
      if (state.offset >= file.size) {
        // Every byte is there; the server is checking and storing the file.
        if (++polls > 120) throw Object.assign(new Error(t("The server is slow to finish. Trying again.", "الخادم بطيء في الإنهاء. إعادة المحاولة.")), { status: 503 })
        await wait(1000)
        state = await status(session.id)
        continue
      }
      try {
        const part = file.slice(state.offset, Math.min(state.offset + CHUNK, file.size))
        const headers = { "Content-Type": "application/octet-stream", "X-Upload-Offset": String(state.offset) }
        const sha = await sha256Hex(part)
        if (sha) headers["X-Chunk-Sha256"] = sha
        state = await call("PATCH", session.id, headers, part)
        tries = 0
        onProgress(Math.min(100, Math.round((state.offset / file.size) * 100)))
      } catch (error) {
        // Out of step (a reply was lost): the server says where it is.
        if (error.status === 409 && typeof error.offset === "number") {
          state = { ...state, offset: error.offset }
          continue
        }
        // The server forgot this upload: start over, once.
        if (error.status === 404 && restarts < 1) {
          restarts += 1
          state = await begin()
          continue
        }
        // The same chunk once more (also when the server found it damaged).
        if ((transient(error) || error.status === 422) && ++tries < 5) {
          await wait(backoff(tries))
          try {
            state = await status(session.id) // maybe it arrived after all
          } catch {
            /* still offline: the next try will say */
          }
          continue
        }
        throw error
      }
    }
  }
  const tooBig = (name) => {
