  }
  /* The chat is fixed when the files are chosen (or the voice note started), so a
     switch while they upload never moves them to another chat. */
  async function sendFiles(files, voice = false, conversationId = active, retryClientId = null) {
    if (!conversationId || !convs.has(conversationId)) return
    if (conversationId === active && chat.dataset.conv !== conversationId) return
    askNotifications()
    for (const raw of files) {
      if (raw.size > limits.fileBytes) {
        toast(tooBig(raw.name))
        continue
      }
      // A retry keeps its id, so the failed bubble turns into the sent one.
      const clientId = retryClientId || uid()
      const kind = voice ? "voice" : /^image\//.test(raw.type) ? "image" : "file"
      const placeholder = { id: "local-" + clientId, clientId, conversationId, sender: ME, kind, body: "", createdAt: new Date().toISOString(), file: { name: raw.name, size: raw.size }, reactions: [], pending: true, upload: { file: raw, voice } }
