      if (active === conversationId) renderMessages({ stick: true })
      try {
        // The same prepared file and upload session on every attempt, so a retry resumes.
        if (!preparedFiles.has(clientId)) preparedFiles.set(clientId, await shrink(raw))
        if (!uploadSessions.has(clientId)) uploadSessions.set(clientId, {})
        const file = await upload(conversationId, preparedFiles.get(clientId), uploadSessions.get(clientId), (pct) => {
          uploadPct.set(clientId, pct)
