      } catch (error) {
        if (!thread(conversationId).list.some((x) => x.clientId === clientId)) {
          // Cancelled: free the server's copy and forget the file.
          abandonUpload(conversationId, uploadSessions.get(clientId))
          preparedFiles.delete(clientId)
          uploadSessions.delete(clientId)
          uploadPct.delete(clientId)
          continue
        }
        if (transient(error)) {
          // Waits for the network and uploads by itself.
          pendingUploads.set(clientId, () => sendFiles([raw], voice, conversationId, clientId))
