  /* Voice notes: tap the mic to record, tap send to finish, the bin to discard.
     MP4 (AAC) is recorded where the browser can: it plays on every phone and its length
     is known. Chrome's WebM recordings carry no duration, which the player works around. */
  const VOICE_TYPES = ["audio/mp4;codecs=mp4a.40.2", "audio/mp4", "audio/webm;codecs=opus", "audio/ogg;codecs=opus", "audio/webm"]
  let recTimer = null,
