  }
  async function toggleRecording() {
    if (recorder) return stopRecording()
    if (recStarting) return // the microphone permission prompt is still open
    if (callUI.busy()) return toast(t("You can't record a voice message during a call.", "لا يمكن تسجيل رسالة صوتية أثناء المكالمة."))
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined")
      return toast(t("This browser cannot record audio.", "هذا المتصفح لا يدعم تسجيل الصوت."))
    // Taken now: switching chats while the permission prompt is open must not move it.
    const conversationId = active
    recStarting = true
    let media
    try {
      media = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } })
    } catch {
      return toast(t("Allow microphone access to record a voice message.", "اسمح بالوصول إلى الميكروفون لتسجيل رسالة صوتية."))
    } finally {
      recStarting = false
    }
    // The chat closed or a call started while the prompt was open: release the mic.
    if (destroyed || active !== conversationId || callUI.busy()) return media.getTracks().forEach((track) => track.stop())
    const type = VOICE_TYPES.find((x) => MediaRecorder.isTypeSupported?.(x)) || ""
    const chunks = []
    const started = Date.now()
    let rec
    try {
      rec = new MediaRecorder(media, type ? { mimeType: type, audioBitsPerSecond: 64000 } : {})
    } catch {
      media.getTracks().forEach((track) => track.stop())
      return toast(t("This browser cannot record audio.", "هذا المتصفح لا يدعم تسجيل الصوت."))
    }
    recorder = rec
    rec.ondataavailable = (e) => e.data.size && chunks.push(e.data)
    rec.onstop = () => {
      media.getTracks().forEach((track) => track.stop())
      clearInterval(recTimer)
      if (recorder === rec) recorder = null
      $(".dm-recording").hidden = true
      input.hidden = false
      resize()
      if (rec.cancelled || Date.now() - started < 800 || !chunks.length) return
      const mime = (chunks[0].type || type || "audio/webm").split(";")[0]
      const ext = mime.includes("ogg") ? "ogg" : mime.includes("mp4") ? "m4a" : "webm"
      sendFiles([new File(chunks, `voice-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.${ext}`, { type: mime })], true, conversationId)
    }
    // A slice every second, so a long note isn't held in one piece until the end.
    rec.start(1000)
    $(".dm-rec-time").textContent = "0:00"
    $(".dm-recording").hidden = false
    input.hidden = true
    sendBtn.innerHTML = svg("send")
    recTimer = setInterval(() => {
      const secs = Math.floor((Date.now() - started) / 1000)
      $(".dm-rec-time").textContent = clock(secs)
      if (secs >= 300) stopRecording()
    }, 250)
  }

  /* One voice note plays at a time, in a WhatsApp-style player: play, seek, speed. */
  const voice = { audio: new Audio(), id: null, rate: 1, fixing: false }
  voice.audio.preload = "auto"
  const voiceDurations = new Map() // message id -> seconds, once known
  function voiceUI(id = voice.id) {
    if (!id) return
    const el = msgsEl.querySelector(`.dm-voice[data-id="${CSS.escape(id)}"]`)
    if (!el) return
    const a = voice.audio
    const current = voice.id === id
    const playing = current && !a.paused
    const total = voiceDurations.get(id)
    const at = current ? a.currentTime : 0
    const button = el.querySelector(".dm-voice-play")
    button.innerHTML = svg(playing ? "pause" : "play")
    button.title = playing ? t("Pause", "إيقاف مؤقت") : t("Play", "تشغيل")
    el.querySelector(".dm-voice-seek").value = total ? String(Math.round((at / total) * 1000)) : "0"
    el.querySelector(".dm-voice-time").textContent = current && at > 0 ? clock(at) : total ? clock(total) : "0:00"
    el.querySelector(".dm-voice-rate").textContent = (current ? voice.rate : 1) + "×"
    el.classList.toggle("dm-playing", playing)
  }
  function syncVoice() {
    msgsEl.querySelectorAll(".dm-voice[data-id]").forEach((el) => voiceUI(el.dataset.id))
  }
  const cantPlay = () => toast(t("This voice message can't play here.", "لا يمكن تشغيل هذه الرسالة الصوتية هنا."))
  async function playVoice(m) {
    const a = voice.audio
    if (voice.id === m.id) {
      if (a.paused) await a.play().catch(cantPlay)
      else a.pause()
      return voiceUI(m.id)
    }
    const previous = voice.id
    a.pause()
    voice.id = m.id
    voice.fixing = false
    a.src = m.file.url
    a.playbackRate = voice.rate
    if (previous) voiceUI(previous)
    await a.play().catch(cantPlay)
    voiceUI(m.id)
  }
  function voiceRate(m) {
    voice.rate = voice.rate === 1 ? 1.5 : voice.rate === 1.5 ? 2 : 1
    if (voice.id === m.id) voice.audio.playbackRate = voice.rate
    voiceUI(m.id)
