    if (a.duration === Infinity) {
      voice.fixing = true
      a.currentTime = 1e101
    } else if (voice.id && Number.isFinite(a.duration)) voiceDurations.set(voice.id, a.duration)
  })
  voice.audio.addEventListener("durationchange", () => {
    const a = voice.audio
    if (!voice.id || !Number.isFinite(a.duration) || a.duration <= 0) return
    voiceDurations.set(voice.id, a.duration)
    if (voice.fixing) {
