  })
  msgsEl.addEventListener("input", (e) => {
    const seek = e.target.closest?.(".dm-voice-seek")
    if (!seek) return
    const id = seek.closest(".dm-voice").dataset.id
    const total = voiceDurations.get(id)
    if (voice.id === id && total) voice.audio.currentTime = (Number(seek.value) / 1000) * total
  })

  /* ---------- incoming events ---------- */
  function onMessage(m, fromSelf = false) {
    const c = convs.get(m.conversationId)
    if (!c) return refreshConv(m.conversationId)
    if (hiddenIds.has(m.id)) return
    const th = thread(m.conversationId)
    const known = th.list.some((x) => x.id === m.id)
    // Edits and reactions re-send old messages. Only a message newer than the chat's
    // latest one is new; the thread may not be loaded, so "not in the list" is not enough.
    const fresh = !known && (!c.last || (c.last.id !== m.id && new Date(m.createdAt) >= new Date(c.last.at)))
