      if (!looking) {
        c.unread = (c.unread || 0) + 1
        if (m.mentionAll || (m.mentions || []).includes(ME)) c.mentioned = true
        if (active === c.id && !c.unreadMarker) c.unreadMarker = m.id
        notify(c, m)
      }
      c.archived = false
      if (looking) readActive(true)
      else delivered()
