  }

  /* ---------- live stream, with a polling fallback ---------- */
  async function connect() {
    if (destroyed) return
    stream?.close()
    stream = null
    let url
    try {
      url = (await api("stream.ticket")).url
    } catch {
      return reconnectLater()
    }
    if (destroyed) return
    const source = new EventSource(url)
    stream = source
    source.addEventListener("ready", () => {
      streamFailures = 0
      streamUp = true
      stopPolling()
      resync()
      kickQueue() // the server is reachable: send what's waiting
      retryUploads()
      renderNet()
    })
    source.addEventListener("message", (e) => onMessage(JSON.parse(e.data).message))
    source.addEventListener("typing", (e) => onTyping(JSON.parse(e.data)))
    source.addEventListener("read", (e) => onRead(JSON.parse(e.data)))
    source.addEventListener("conversation", (e) => refreshConv(JSON.parse(e.data).conversationId))
    source.addEventListener("call", (e) => {
      const call = JSON.parse(e.data).call
      if (!call) return
      callEvents.set(call.id, Date.now())
      onCall(call)
    })
    source.addEventListener("reconnect", () => {
      source.close()
      if (stream === source) connect()
    })
    source.onerror = () => {
      if (stream !== source) return
      source.close()
      stream = null
      streamUp = false
      renderNet()
      reconnectLater()
    }
  }
  function reconnectLater() {
    streamFailures += 1
    if (streamFailures >= 3) startPolling()
    // With jitter, so many browsers coming back at once don't reconnect in lockstep.
    later(connect, Math.min(30_000, 1000 * 2 ** Math.min(streamFailures, 5)) * (0.5 + Math.random() * 0.5))
