  /* Catches up after a reconnect: chat list, then the open chat's latest page. */
  async function resync() {
    try {
      const before = active ? convs.get(active)?.last?.id : null
      const { conversations } = await api("conversations.list")
      const seen = new Set()
      for (const c of conversations) {
        seen.add(c.id)
        mergeConv(c)
      }
      for (const id of [...convs.keys()]) if (!seen.has(id)) convs.delete(id)
      for (const [id, th] of threads) if (id !== active) th.stale = true
      if (active && convs.get(active)?.last?.id !== before) await loadMessages(active)
      if (active) loadPins(active)
      if (limits.callsEnabled) {
        // Calls rang or ended while the live connection was down.
        const asked = Date.now()
        const { calls } = await api("calls.live")
        // Live events that arrived while this was on its way are newer: keep them.
        const newer = (id) => (callEvents.get(id) || 0) >= asked
        const now = new Set(calls.map((call) => call.conversationId))
        for (const [conversationId, call] of [...liveCalls])
          if (!now.has(conversationId) && !newer(call.id)) onCall({ ...call, endedAt: new Date().toISOString() })
        calls.filter((call) => !newer(call.id)).forEach(onCall)
      }
      if (active) renderHead()
      renderList()
    } catch {
      /* try again on the next tick */
    }
  }
  async function refreshPresence(users) {
    try {
      const { lastSeen } = await api("presence", { users })
