      height = pop.offsetHeight
    let left = ar ? at.left - box.left : at.right - box.left - width
    left = Math.max(8, Math.min(left, box.width - width - 8))
    let top = at.bottom - box.top + 4
    if (top + height > box.height - 8) top = Math.max(8, at.top - box.top - height - 4)
    pop.style.left = left + "px"
    pop.style.top = top + "px"
  }
