  async function squarePhoto(file) {
    try {
      const bitmap = await createImageBitmap(file)
      const crop = Math.min(bitmap.width, bitmap.height)
      const canvas = document.createElement("canvas")
      canvas.width = canvas.height = Math.min(crop, 512)
      const ctx = canvas.getContext("2d")
      ctx.fillStyle = "#fff" // a transparent PNG would otherwise turn black as a JPEG
      ctx.fillRect(0, 0, canvas.width, canvas.height)
      ctx.drawImage(bitmap, (bitmap.width - crop) / 2, (bitmap.height - crop) / 2, crop, crop, 0, 0, canvas.width, canvas.height)
      const blob = await new Promise((done) => canvas.toBlob(done, "image/jpeg", 0.85))
      return blob ? new File([blob], "group.jpg", { type: "image/jpeg" }) : file
    } catch {
      return file
    }
  }
  async function setGroupPhoto(id, picked) {
    if (!picked) return
    if (!/^image\/(png|jpeg|webp|gif)$/.test(picked.type)) return fail(new Error(t("Choose a PNG, JPEG, WebP or GIF picture.", "اختر صورة بصيغة PNG أو JPEG أو WebP أو GIF.")))
    try {
      const file = await squarePhoto(picked)
      const ticket = await api("files.ticket", { conversationId: id, avatar: true })
      const response = await fetch(ticket.url, {
        method: "POST",
        mode: "cors",
        credentials: "omit",
        headers: { "Content-Type": file.type, "X-File-Name": encodeURIComponent(file.name || "group.jpg") },
        body: file,
      })
      const body = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(body.error || t("Upload failed.", "فشل الرفع."))
      await groupAction("groups.image", { conversationId: id, fileId: body.file.id })
    } catch (error) {
