  /* ---------- voice and video calls ----------
     Audio and video go through the company's own LiveKit server; the panel records who
     was called and how each call ended. The call window is attached to the page, not to
     this block, so a call keeps going while the employee moves around ERP. */
  const CALL_SDK = {
    src: "https://cdn.jsdelivr.net/npm/livekit-client@2.22.4/dist/livekit-client.umd.js",
    integrity: "sha384-5qI/UmLG0CvuWCt6vqjMW1oRwzXu+MNhbw4x6yo9NARdlqi94LwQfq9wvDTIcfrD",
  }
  const RING_SECONDS = 45
  const liveCalls = new Map() // conversationId -> live call in one of my chats
  const callEvents = new Map() // call id -> when its last live event came
  let callLog = null
  const clock = (seconds) => {
    const s = Math.max(0, Math.floor(seconds))
    const h = Math.floor(s / 3600)
    const mm = String(Math.floor((s % 3600) / 60))
    const ss = String(s % 60).padStart(2, "0")
    return h ? `${h}:${mm.padStart(2, "0")}:${ss}` : `${mm}:${ss}`
  }
  function loadSdk() {
    if (window.LivekitClient) return Promise.resolve(window.LivekitClient)
    if (!window.__durarLivekit)
      window.__durarLivekit = new Promise((resolve, reject) => {
        const script = document.createElement("script")
        script.src = CALL_SDK.src
        script.integrity = CALL_SDK.integrity
        script.crossOrigin = "anonymous"
        script.onload = () => (window.LivekitClient ? resolve(window.LivekitClient) : reject(new Error("sdk")))
        script.onerror = () => {
          window.__durarLivekit = null
          script.remove()
          reject(new Error(t("Calls could not load. Check your connection.", "تعذر تحميل المكالمات. تحقق من الاتصال.")))
        }
        document.head.appendChild(script)
      })
    return window.__durarLivekit
  }
  /* Ring and ring-back tones are synthesised, so there's no sound file to host. Browsers
     allow sound only after someone has used the page; the first click unlocks it. */
  const tones = window.__durarCallTones || (window.__durarCallTones = { ctx: null, timer: null, beeps: [] })
  function unlockAudio() {
    try {
      tones.ctx = tones.ctx || new (window.AudioContext || window.webkitAudioContext)()
      if (tones.ctx.state === "suspended") tones.ctx.resume()
    } catch {
      /* no Web Audio: calls still work, just without tones */
    }
  }
  document.addEventListener("pointerdown", unlockAudio, { capture: true, passive: true })
  function beep(freqs, seconds) {
    const ctx = tones.ctx
    if (!ctx || ctx.state !== "running") return
    const now = ctx.currentTime
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(0.12, now + 0.03)
    gain.gain.setValueAtTime(0.12, now + seconds - 0.05)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + seconds)
    gain.connect(ctx.destination)
    for (const f of freqs) {
      const osc = ctx.createOscillator()
      osc.frequency.value = f
      osc.connect(gain)
      osc.start(now)
      osc.stop(now + seconds)
    }
  }
  // "ring": someone is calling you. "back": the person you're calling is being rung.
  function playTone(kind) {
    stopTone()
    const once = () => {
      if (kind === "ring") {
        beep([440, 480], 0.4)
        tones.beeps.push(setTimeout(() => beep([440, 480], 0.4), 600))
      } else beep([425], 1)
    }
    once()
    tones.timer = setInterval(once, kind === "ring" ? 3000 : 4000)
  }
  function stopTone() {
    clearInterval(tones.timer)
    tones.timer = null
    tones.beeps.forEach(clearTimeout)
    tones.beeps = []
  }

  function createCallUI() {
    const hostEl = document.createElement("div")
    hostEl.className = "durar-messenger-call"
    document.body.appendChild(hostEl)
    const shadow = hostEl.attachShadow({ mode: "open" })
    for (const style of host.querySelectorAll("style")) shadow.appendChild(style.cloneNode(true))
    const layer = document.createElement("div")
    layer.className = "dm dm-call-layer"
    layer.dir = root.dir
    layer.innerHTML = `
      <section class="dm-call" hidden role="dialog" aria-modal="true" aria-label="${t("Call", "مكالمة")}">
        <header class="dm-call-top"><div class="dm-call-head"></div>
          <button class="dm-icon" data-call="minimize" title="${t("Minimise", "تصغير")}">${svg("minimize")}</button></header>
        <div class="dm-call-stage"></div>
        <p class="dm-call-note" hidden></p>
        <footer class="dm-call-controls"></footer>
      </section>
      <button class="dm-call-pill" data-call="restore" hidden></button>
      <div class="dm-call-audio" hidden></div>`
    shadow.appendChild(layer)
    const panel = layer.querySelector(".dm-call"),
      stage = layer.querySelector(".dm-call-stage"),
      note = layer.querySelector(".dm-call-note"),
      bar = layer.querySelector(".dm-call-controls"),
      head = layer.querySelector(".dm-call-head"),
      pill = layer.querySelector(".dm-call-pill"),
      audioBox = layer.querySelector(".dm-call-audio")
    const canShare = !!navigator.mediaDevices?.getDisplayMedia && !/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent)
    const savedTitle = { value: null } // the tab title while an incoming call shows its caller
    let s = null // the current call; null when idle
    let endedTimer = null
    const videoEls = new Map() // track sid -> its <video>, so re-rendering never restarts a stream

    const conv = () => convs.get(s.conversationId)
    const title = () => {
      const c = conv()
      return c ? convTitle(c) : person(s.call?.startedBy || ME).name
    }
    const face = () => {
      const c = conv()
      if (c?.kind === "group") return avatar(null, "dm-xl", c)
      return avatar(s.mode === "incoming" ? s.call.startedBy : c?.peer || s.call?.startedBy || ME, "dm-xl")
    }
    const elapsed = () => (s?.answeredAt ? clock((Date.now() - s.answeredAt) / 1000) : "")
    function status() {
      if (s.mode === "incoming") return s.video ? t("Incoming video call", "مكالمة فيديو واردة") : t("Incoming voice call", "مكالمة صوتية واردة")
      if (s.mode === "outgoing") return s.room ? t("Ringing…", "يرن…") : t("Calling…", "جارٍ الاتصال…")
      if (s.mode === "connecting") return t("Connecting…", "جارٍ الاتصال…")
      const n = s.room ? s.room.remoteParticipants.size : 0
      if (conv()?.kind === "group" && !n) return t("Waiting for others…", "بانتظار الآخرين…")
      return elapsed()
    }
    function trackOf(participant, source) {
      const pub = participant.getTrackPublication(source)
      return pub && pub.track && !pub.isMuted ? pub.track : null
    }
    // Call video always shows whole (the CSS letterboxes it). Your own small corner
    // picture takes your camera's shape, so it is never cropped either.
    function fit(video) {
      const box = video.parentElement
      if (!box || !box.classList.contains("dm-tile") || !video.videoWidth || !video.videoHeight) return
      box.style.setProperty("--ar", `${video.videoWidth} / ${video.videoHeight}`)
      box.dataset.shape = video.videoWidth > video.videoHeight ? "wide" : "tall"
      // The corner picture (one-to-one) takes the camera's shape even with an old Style.
      box.style.aspectRatio =
        box.classList.contains("dm-tile-me") && stage.dataset.count === "1" ? `${video.videoWidth} / ${video.videoHeight}` : ""
    }
    const refit = () => stage.querySelectorAll(".dm-tile video").forEach(fit)
    if (typeof ResizeObserver === "function") new ResizeObserver(refit).observe(stage)
    function videoFor(track) {
      let el = videoEls.get(track.sid)
      if (!el) {
        el = track.attach()
        el.muted = true
        el.playsInline = true
        // "resize" also fires when the other person turns their phone.
        el.addEventListener("loadedmetadata", () => fit(el))
        el.addEventListener("resize", () => fit(el))
        videoEls.set(track.sid, el)
      }
      return el
    }
    // Call video is never cropped: the whole picture, with black bars where its shape and
    // the tile's differ (an upright phone on a wide laptop screen). Set here as well as in
    // the Style, so it holds even when ERP still has an older Style saved. Only your own
    // corner picture fills its box, which already has your camera's shape.
    // The video is pinned to its box. Left in the tile's grid, it took its own height
    // (a phone's upright 1280px, or a wide picture stretched across a laptop screen),
    // grew taller than the tile and was cut off top and bottom: the "zoomed in" look,
    // whatever object-fit said.
    function letterbox(video, fill) {
      Object.assign(video.style, {
        position: "absolute",
        inset: "0",
        width: "100%",
        height: "100%",
        minWidth: "0",
        minHeight: "0",
        objectFit: fill ? "cover" : "contain",
        background: "#000",
      })
    }
    function tile(participant, local, corner = false) {
      const { Track } = window.LivekitClient
      const screen = trackOf(participant, Track.Source.ScreenShare)
      const cam = trackOf(participant, Track.Source.Camera)
      const el = document.createElement("div")
      el.className = `dm-tile${local ? " dm-tile-me" : ""}${participant.isSpeaking ? " dm-speaking" : ""}`
      el.dataset.who = participant.identity
      const track = screen || cam
      if (track) {
        const video = videoFor(track)
        video.classList.toggle("dm-mirror", !!local && !screen)
        video.classList.toggle("dm-contain", !!screen)
        video.classList.remove("dm-call-backdrop")
        letterbox(video, corner && !screen)
        el.appendChild(video)
        fit(video) // the shape now; whether to fill is settled once the tile is laid out
      } else el.insertAdjacentHTML("beforeend", `<div class="dm-tile-face">${avatar(participant.identity, "dm-xl")}</div>`)
      const micOff = !trackOf(participant, Track.Source.Microphone)
      el.insertAdjacentHTML(
        "beforeend",
        `<span class="dm-tile-name">${micOff ? svg("micOff") : ""}${esc(local ? t("You", "أنت") : person(participant.identity).name)}</span>`
      )
      return el
    }
    function renderStage() {
      if (!s) return
      const used = new Set()
      const keep = (el) => {
        const video = el.querySelector("video")
        if (video) for (const [sid, v] of videoEls) if (v === video) used.add(sid)
        return el
      }
      const nodes = []
      const room = s.room
      const remotes = room ? [...room.remoteParticipants.values()] : []
      if (s.mode !== "active" || !remotes.length) {
        // Ringing or alone: who you're talking to, over your own camera on a video call.
        if (room && s.cameraOn && window.LivekitClient) {
          const cam = trackOf(room.localParticipant, window.LivekitClient.Track.Source.Camera)
          if (cam) {
            const v = videoFor(cam)
            v.classList.add("dm-mirror", "dm-call-backdrop")
            letterbox(v, false)
            used.add(cam.sid)
            nodes.push(v)
          }
        }
        const card = document.createElement("div")
        card.className = "dm-call-card"
        card.innerHTML = `${face()}<b>${esc(title())}</b><small class="dm-call-status">${esc(status())}</small>`
        nodes.push(card)
        stage.dataset.count = "0"
      } else {
        for (const p of remotes) nodes.push(keep(tile(p, false)))
        // One-to-one: you are the small corner picture.
        nodes.push(keep(tile(room.localParticipant, true, remotes.length === 1)))
        stage.dataset.count = String(Math.min(remotes.length, 9))
      }
      stage.replaceChildren(...nodes)
      for (const sid of [...videoEls.keys()]) if (!used.has(sid)) videoEls.delete(sid)
      requestAnimationFrame(refit)
    }
    function renderControls() {
      const b = (act, icon, label, cls = "") =>
        `<button class="dm-call-ctl ${cls}" data-call="${act}" title="${esc(label)}" aria-label="${esc(label)}">${svg(icon)}<span>${esc(label)}</span></button>`
      if (s.mode === "incoming") {
        bar.innerHTML =
          b("decline", "hangup", t("Decline", "رفض"), "dm-call-end") +
          (s.video
            ? b("accept-voice", "phone", t("Voice only", "صوت فقط"), "dm-call-ok") + b("accept-video", "video", t("Accept", "قبول"), "dm-call-ok")
            : b("accept-voice", "phone", t("Accept", "قبول"), "dm-call-ok"))
        return
      }
      bar.innerHTML =
        b("mic", s.micOn ? "mic" : "micOff", s.micOn ? t("Mute", "كتم الصوت") : t("Unmute", "إلغاء الكتم"), s.micOn ? "" : "dm-off") +
        b("camera", s.cameraOn ? "video" : "videoOff", s.cameraOn ? t("Camera off", "إيقاف الكاميرا") : t("Camera on", "تشغيل الكاميرا"), s.cameraOn ? "" : "dm-off") +
        (s.cameraOn && s.cameras > 1 ? b("flip", "flip", t("Switch camera", "تبديل الكاميرا")) : "") +
        (canShare ? b("screen", "screen", s.screenOn ? t("Stop sharing", "إيقاف المشاركة") : t("Share screen", "مشاركة الشاشة"), s.screenOn ? "dm-on" : "") : "") +
        b("hangup", "hangup", t("End call", "إنهاء المكالمة"), "dm-call-end")
    }
    function renderNote() {
      if (!s) return
      const room = s.room
      if (s.reconnecting) {
        note.hidden = false
        note.textContent = t("Reconnecting…", "جارٍ إعادة الاتصال…")
      } else if (room && room.canPlaybackAudio === false) {
        note.hidden = false
        note.innerHTML = `<button data-call="enable-audio">${svg("speaker")} ${t("Tap to hear the call", "اضغط لسماع المكالمة")}</button>`
      } else note.hidden = true
    }
    function render() {
      if (!s) {
        panel.hidden = true
        pill.hidden = true
        return
      }
      clearTimeout(endedTimer)
      panel.classList.remove("dm-call-over")
      panel.dataset.mode = s.mode
      panel.hidden = !!s.minimized
      pill.hidden = !s.minimized
      head.innerHTML = `<b>${esc(title())}</b><small class="dm-call-status">${esc(status())}</small>`
      pill.innerHTML = `<span class="dm-dot"></span>${esc(title())} · <span class="dm-call-status">${esc(status())}</span>`
      renderControls()
      renderStage()
      renderNote()
      onCallsChanged()
    }
    function tick() {
      if (!s) return
      layer.querySelectorAll(".dm-call-status").forEach((el) => (el.textContent = status()))
    }
    function answered() {
      if (!s || s.mode === "active") return
      stopTone()
      clearTimeout(s.ringTimer)
      s.mode = "active"
      // Joining a call already under way shows its real length.
      s.answeredAt = s.call?.answeredAt ? Math.min(Date.now(), Date.parse(s.call.answeredAt)) : Date.now()
      render()
    }
    async function countCameras() {
      try {
        s.cameras = (await window.LivekitClient.Room.getLocalDevices("videoinput")).length
      } catch {
        s.cameras = 1
      }
    }
    async function connect(url, token) {
      const LK = window.LivekitClient
      const current = s
      const room = new LK.Room({
        adaptiveStream: true,
        dynacast: true,
        audioCaptureDefaults: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      })
      current.room = room
      room.on("participantConnected", () => {
        answered()
        renderStage()
      })
      room.on("participantDisconnected", () => {
        if (s !== current) return
        render()
        // One-to-one: the other person has gone, so the call is over. The server
        // normally says so first; wait a moment in case they're only moving the call to
        // another device (which reconnects them under the same name).
        if (conv()?.kind === "group") return
        clearTimeout(current.goneTimer)
        current.goneTimer = setTimeout(() => {
          if (s === current && !current.ending && !room.remoteParticipants.size) end(t("Call ended", "انتهت المكالمة"), true)
        }, 8000)
      })
      room.on("trackSubscribed", (track) => {
        if (track.kind === "audio") audioBox.appendChild(track.attach())
        renderStage()
      })
      room.on("trackUnsubscribed", (track) => {
        track.detach().forEach((el) => el.remove())
        renderStage()
      })
      for (const event of ["trackMuted", "trackUnmuted", "localTrackPublished", "localTrackUnpublished"])
        room.on(event, () => s === current && renderStage())
      room.on("activeSpeakersChanged", (speakers) => {
        const ids = new Set(speakers.map((p) => p.identity))
        stage.querySelectorAll("[data-who]").forEach((el) => el.classList.toggle("dm-speaking", ids.has(el.dataset.who)))
      })
      room.on("audioPlaybackChanged", () => s === current && renderNote())
      room.on("reconnecting", () => {
        if (s !== current) return
        current.reconnecting = true
        renderNote()
      })
      room.on("reconnected", () => {
        if (s !== current) return
        current.reconnecting = false
        renderNote()
      })
      // LiveKit's DisconnectReason: 2 the same person joined from another device, 4 or 5
      // the server removed them or closed the call's room.
      room.on("disconnected", (reason) => {
        if (s !== current || current.ending) return
        if (reason === 2) return end(t("The call continued on your other device.", "استمرت المكالمة على جهازك الآخر."), false)
        if (reason === 4 || reason === 5) return end(t("Call ended", "انتهت المكالمة"), false)
        end(t("The call dropped. Check your connection.", "انقطعت المكالمة. تحقق من الاتصال."), true, true)
      })
      await room.connect(url, token)
      if (s !== current || current.ending) return room.disconnect()
      try {
        await room.localParticipant.setMicrophoneEnabled(true)
      } catch {
        current.micOn = false
        toast(t("Allow the microphone so others can hear you.", "اسمح بالميكروفون ليسمعك الآخرون."))
      }
      if (current.cameraOn)
        try {
          await room.localParticipant.setCameraEnabled(true)
          await countCameras()
        } catch {
          current.cameraOn = false
          toast(t("Allow the camera to share video.", "اسمح بالكاميرا لمشاركة الفيديو."))
        }
      if (s !== current) return
      if (room.remoteParticipants.size) answered()
      else render()
    }
    function fresh(call, mode, video) {
      return { call, mode, video, conversationId: call?.conversationId, micOn: true, cameraOn: video, cameras: 1, timer: setInterval(tick, 1000) }
    }
    async function start(conversationId, video) {
      if (s) return toast(t("You're already in a call.", "أنت في مكالمة بالفعل."))
      unlockAudio()
      s = { ...fresh(null, "outgoing", video), conversationId }
      const current = s
      render()
      try {
        const [result] = await Promise.all([api("calls.start", { conversationId, video }), loadSdk()])
        if (s !== current) return api("calls.leave", { callId: result.call.id }).catch(() => {})
        current.call = result.call
        if (result.call.answeredAt) current.mode = "connecting" // joined a call already under way
        render()
        const early = current.early
        current.early = null
        if (early?.id === result.call.id) {
          update(early) // declined or ended before its id came back
          if (s !== current) return
        }
        await connect(result.url, result.token)
        if (s === current && current.mode === "outgoing") {
          playTone("back")
          current.ringTimer = setTimeout(() => s === current && current.mode === "outgoing" && end(t("No answer", "لا يوجد رد"), true), RING_SECONDS * 1000)
        }
      } catch (error) {
        if (s === current) end(error.message || t("The call couldn't start.", "تعذر بدء المكالمة."), true)
      }
    }
    // answer: pressed Answer on a ringing call (refused if answered on another device).
    async function join(call, video, answer = false) {
      const current = s && s.call?.id === call.id ? s : null
      if (s && !current) return toast(t("You're already in a call.", "أنت في مكالمة بالفعل."))
      unlockAudio()
      stopTone()
      if (current) {
        clearTimeout(current.ringTimer)
        current.notice?.close()
        Object.assign(current, { mode: "connecting", video, cameraOn: video })
      } else s = fresh(call, "connecting", video)
      const mine = s
      restoreTitle()
      render()
      try {
        const [result] = await Promise.all([api("calls.join", { callId: call.id, ...(answer ? { answer: true } : {}) }), loadSdk()])
        if (s !== mine) return api("calls.leave", { callId: call.id }).catch(() => {})
        mine.call = result.call
        await connect(result.url, result.token)
        if (s === mine && mine.room?.remoteParticipants.size) answered()
      } catch (error) {
        if (s === mine) end(error.message || t("Couldn't join the call.", "تعذر الانضمام إلى المكالمة."), true)
      }
    }
    function restoreTitle() {
      if (savedTitle.value !== null) document.title = savedTitle.value
      savedTitle.value = null
    }
    function incoming(call) {
      s = fresh(call, "incoming", call.video)
      const current = s
      playTone("ring")
      navigator.vibrate?.([400, 200, 400, 200, 400])
      if (savedTitle.value === null) savedTitle.value = document.title
      document.title = "📞 " + person(call.startedBy).name
      if (document.hidden && "Notification" in window && Notification.permission === "granted")
        try {
          current.notice = new Notification(person(call.startedBy).name, {
            body: status(),
            tag: "durar-call-" + call.id,
            requireInteraction: true,
          })
          current.notice.onclick = () => window.focus()
        } catch {
          /* notifications are optional */
        }
      // The caller gives up after RING_SECONDS; stop ringing here a little after that.
      current.ringTimer = setTimeout(() => s === current && current.mode === "incoming" && end(t("Missed call", "مكالمة فائتة"), false), (RING_SECONDS + 10) * 1000)
      loadSdk().catch(() => {}) // ready by the time they answer
      render()
      bar.querySelector(".dm-call-ok:last-child")?.focus()
    }
    // tellServer: this person ended it (hang up, decline, failure). Otherwise the server
    // or the other side already did.
    function end(message = "", tellServer = false, dropped = false) {
      if (!s || s.ending) return
      const current = s
      current.ending = true
      stopTone()
      clearTimeout(current.ringTimer)
      clearTimeout(current.goneTimer)
      clearInterval(current.timer)
      current.notice?.close()
      restoreTitle()
      if (tellServer && current.call && !current.call.endedAt)
        api(current.mode === "incoming" ? "calls.decline" : "calls.leave", { callId: current.call.id, ...(dropped ? { dropped: true } : {}) }).catch(() => {})
      current.room?.disconnect()
      audioBox.replaceChildren()
      videoEls.clear()
      s = null
      onCallsChanged()
      if (!message) return render()
      // A moment to read how the call ended, unless another call starts first.
      pill.hidden = true
      panel.hidden = false
      panel.classList.add("dm-call-over")
      bar.innerHTML = ""
      note.hidden = true
      stage.innerHTML = `<div class="dm-call-card"><b>${esc(message)}</b></div>`
      endedTimer = setTimeout(() => !s && render(), 1800)
    }
    // Every change to a call in my chats arrives here (live events, start-up, catch-up).
    function update(call) {
      const mine = call.members.find((m) => m.user === ME)?.state
      if (s && !s.call && s.mode === "outgoing" && call.conversationId === s.conversationId) {
        s.early = call
        return
      }
      if (s?.call?.id === call.id) {
        s.call = call
        // Declined on another device (the phone app): nothing was missed.
        if (call.endedAt && s.mode === "incoming" && mine === "declined") return end()
        if (call.endedAt) {
          const missed = s.mode === "incoming"
          return end(missed ? t("Missed call", "مكالمة فائتة") : s.mode === "outgoing" ? (call.endReason === "declined" ? t("Declined", "مرفوض") : t("No answer", "لا يوجد رد")) : t("Call ended", "انتهت المكالمة"))
        }
        // Answered or declined on another device: stop ringing here.
        if (s.mode === "incoming" && mine !== "ringing") return end()
        return render()
      }
      if (!call.endedAt && mine === "ringing" && call.startedBy !== ME) {
        if (!s) incoming(call)
        else toast(t(`${person(call.startedBy).name} is calling you`, `${person(call.startedBy).name} يتصل بك`))
      }
    }
    layer.addEventListener("click", async (e) => {
      const el = e.target.closest("[data-call]")
      if (!el || !s) return
      const room = s.room
      const act = el.dataset.call
      try {
        if (act === "minimize" || act === "restore") {
          s.minimized = act === "minimize"
          return render()
        }
        if (act === "decline" || act === "hangup") return end("", true)
        if (act === "accept-voice" || act === "accept-video") return join(s.call, act === "accept-video", true)
        if (!room) return
        if (act === "enable-audio") {
          await room.startAudio()
          return renderNote()
        }
        if (act === "mic") {
          await room.localParticipant.setMicrophoneEnabled(!s.micOn)
          s.micOn = !s.micOn
        } else if (act === "camera") {
          await room.localParticipant.setCameraEnabled(!s.cameraOn)
          s.cameraOn = !s.cameraOn
          if (s.cameraOn) await countCameras()
        } else if (act === "flip") {
          const cams = await window.LivekitClient.Room.getLocalDevices("videoinput")
          s.cameraIndex = ((s.cameraIndex || 0) + 1) % cams.length
          await room.switchActiveDevice("videoinput", cams[s.cameraIndex].deviceId)
        } else if (act === "screen") {
          await room.localParticipant.setScreenShareEnabled(!s.screenOn)
          s.screenOn = !s.screenOn
        }
        render()
      } catch {
        if (act === "screen") return // the person cancelled the browser's picker
        toast(act === "camera" ? t("Allow the camera to share video.", "اسمح بالكاميرا لمشاركة الفيديو.") : t("Allow the microphone so others can hear you.", "اسمح بالميكروفون ليسمعك الآخرون."))
      }
    })
    // Keys pressed in the call window stay out of ERP's shortcuts, like in the block.
    for (const type of ["keydown", "keyup", "keypress"]) layer.addEventListener(type, (e) => e.stopPropagation())
    // Closing or reloading the tab during a call asks first.
    window.addEventListener("beforeunload", (e) => {
      if (s && (s.mode === "active" || s.mode === "connecting")) e.preventDefault()
    })
    return {
      start,
      join: (call, video = false) => join(call, video),
      update,
      busy: () => !!s,
      inCall: (id) => s?.call?.id === id,
      setTheme: (theme) => (layer.dataset.theme = theme || ""),
      dispose() {
        stopTone()
        hostEl.remove()
      },
    }
  }
  /* One call window for the whole page. A new block takes it over when it's idle; one
     that is mid-call stays with the block that started it. */
  if (window.__durarCallUI && !window.__durarCallUI.busy()) {
    window.__durarCallUI.dispose()
    window.__durarCallUI = null
  }
  const callUI = window.__durarCallUI || (window.__durarCallUI = createCallUI())
  callUI.setTheme(root.dataset.theme)
  function onCallsChanged() {
    if (active && !destroyed) renderHead()
  }
  function onCall(call) {
    if (call.endedAt) liveCalls.delete(call.conversationId)
    else liveCalls.set(call.conversationId, call)
    callUI.update(call)
    if (active === call.conversationId) renderHead()
    if (call.endedAt && tab === "calls") loadCallLog()
  }
  function startCall(conversationId, video) {
    if (!limits.callsEnabled) return toast(t("Calls aren't set up yet.", "المكالمات غير مفعلة بعد."))
    stopRecording() // a voice note in progress is sent before the call starts
    callUI.start(conversationId, video)
  }
  async function loadCallLog() {
    try {
      callLog = (await api("calls.list")).calls
      if (tab === "calls") renderList()
    } catch (error) {
      fail(error)
    }
  }
  function callLogHtml() {
    if (!limits.callsEnabled) return `<p class="dm-none">${t("Calls aren't set up yet.", "المكالمات غير مفعلة بعد.")}</p>`
    if (!callLog) return `<p class="dm-none">${t("Loading calls…", "جارٍ تحميل المكالمات…")}</p>`
    const rows = callLog.filter((call) => {
      const c = convs.get(call.conversationId)
      return c && matches(convTitle(c))
    })
    if (!rows.length) return `<p class="dm-none">${t("No calls yet. Open a chat and press the phone or camera.", "لا توجد مكالمات بعد. افتح محادثة واضغط على الهاتف أو الكاميرا.")}</p>`
    return rows
      .map((call) => {
        const c = convs.get(call.conversationId)
        const outgoing = call.startedBy === ME
        const mine = call.members.find((m) => m.user === ME)?.state
        const missed = !outgoing && !!call.endedAt && mine === "missed"
        const seconds = call.answeredAt && call.endedAt ? (new Date(call.endedAt) - new Date(call.answeredAt)) / 1000 : 0
        const what = !call.endedAt
          ? t("Ongoing", "جارية")
          : call.endReason === "completed"
            ? clock(seconds)
            : missed
              ? t("Missed", "فائتة")
              : call.endReason === "declined"
                ? t("Declined", "مرفوضة")
                : outgoing
                  ? t("No answer", "لا يوجد رد")
                  : t("Missed", "فائتة")
        return `<div class="dm-row dm-call-row${missed ? " dm-missed" : ""}" data-conv="${esc(c.id)}" role="listitem">
          ${c.kind === "group" ? avatar(null, "", c) : avatar(c.peer || ME)}
          <span class="dm-row-main"><span class="dm-row-top"><b>${esc(convTitle(c))}</b><time>${esc(listTime(call.startedAt))}</time></span>
          <span class="dm-row-sub"><span class="dm-preview"><i class="dm-call-dir">${outgoing ? "↗" : "↙"}</i>${esc(call.video ? t("Video", "فيديو") : t("Voice", "صوت"))} · ${esc(what)}</span></span></span>
          <button class="dm-icon" data-act="call-conv" data-conv="${esc(c.id)}" data-video="${call.video ? "1" : ""}" title="${esc(t("Call back", "معاودة الاتصال"))}">${svg(call.video ? "video" : "phone")}</button>
        </div>`
      })
      .join("")
  }

  /* ---------- start and stop ---------- */
  const presenceTimer = setInterval(() => {
    const c = convs.get(active)
    if (c?.kind === "direct" && c.peer && !document.hidden) refreshPresence([c.peer])
  }, 60_000)
  const directoryTimer = setInterval(() => !document.hidden && loadDirectory(), 5 * 60_000)
  /* Frappe removes the block when the employee leaves the workspace; stop with it. */
  const aliveTimer = setInterval(() => !root.isConnected && destroy(), 5000)
  function destroy() {
    if (destroyed) return
    destroyed = true
    stream?.close()
    stopPolling()
    stopRecording()
    voice.audio.pause()
    voice.audio.removeAttribute("src")
    for (const id of timers) clearTimeout(id)
    for (const map of typing.values()) for (const id of map.values()) clearTimeout(id)
    clearInterval(presenceTimer)
    clearInterval(directoryTimer)
    clearInterval(aliveTimer)
    clearInterval(recTimer)
    themeWatch.disconnect()
    sizeWatch.disconnect()
    document.removeEventListener("visibilitychange", onVisible)
    window.removeEventListener("online", backOnline)
    window.removeEventListener("offline", onOffline)
    window.removeEventListener("storage", onStorage)
    window.removeEventListener("beforeunload", onLeave)
    clearTimeout(draftTimer)
    writeStore("drafts", Object.fromEntries([...drafts].filter(([, text]) => text.trim())))
    document.removeEventListener("pointerdown", unlockAudio, { capture: true })
    if (window.__durarCallUI === callUI && !callUI.busy()) {
      callUI.dispose()
      window.__durarCallUI = null
    }
    document.title = baseTitle()
    root.remove()
  }
  host.__durarMessengerDestroy = destroy

  let bootTries = 0
  async function bootUp() {
    list.innerHTML = `<p class="dm-none">${t("Loading chats…", "جارٍ تحميل المحادثات…")}</p>`
    try {
      const boot = await api("bootstrap")
      me = boot.me
      limits = { ...limits, ...boot.limits, translation: !!boot.translation, callsEnabled: !!boot.callsEnabled }
      people.set(ME, { ...me })
      for (const c of boot.conversations) mergeConv(c)
      renderMe()
      renderList()
      resize()
      for (const call of boot.calls || []) onCall(call)
    } catch (error) {
      list.innerHTML = `<p class="dm-none dm-error">${esc(error.message)}</p>`
      // Offline or the server restarting: start again by itself.
      if (transient(error) && !destroyed) later(bootUp, backoff(bootTries++))
      return
    }
    booted = true
    restoreQueue()
    kickQueue()
    await loadDirectory()
    connect()
  }
  bootUp()
})()

style:
/* Durar Messenger (مراسلة درر). Paste into a Frappe Custom HTML Block's Style field. */
/* Generated by build_agent_blocks.py from messenger.css. Edit the template, not this copy. */
:host {
  display: block;
}
.dm {
  --bg: #fff;
  --side: #fff;
  --panel: #f0f2f5;
  --chat: #efeae2;
  --text: #111b21;
  --sub: #54656f;
  --muted: #667781;
  --line: #e9edef;
  --hover: #f5f6f6;
  --on: #f0f2f5;
  --in: #fff;
  --out: #d8f3e4;
  --accent: #0f766e;
  --accent-fg: #fff;
  --read: #0284c7;
  --danger: #d92d20;
  --badge: #0f9d76;
  --shadow: 0 6px 24px rgba(11, 20, 26, 0.16);
  position: relative;
  display: flex;
  height: calc(100vh - 140px);
  min-height: 520px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--bg);
  color: var(--text);
  font: 14.5px/1.45 "Segoe UI", -apple-system, BlinkMacSystemFont, Inter, system-ui, Roboto, Tahoma, Arial, sans-serif;
  text-align: start;
  -webkit-font-smoothing: antialiased;
}
.dm[data-theme="dark"] {
  --bg: #111b21;
  --side: #111b21;
  --panel: #202c33;
  --chat: #0b141a;
  --text: #e9edef;
  --sub: #aebac1;
  --muted: #8696a0;
  --line: #222d34;
  --hover: #202c33;
  --on: #2a3942;
  --in: #202c33;
  --out: #134d3f;
  --accent: #2dd4bf;
  --accent-fg: #06221d;
  --read: #53bdeb;
  --danger: #f2706a;
  --badge: #2dd4bf;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);
}
.dm *,
.dm *::before,
.dm *::after {
  box-sizing: border-box;
}
.dm [hidden] {
  display: none !important;
}
/* :where keeps the reset at zero specificity so component padding and colours win. */
:where(.dm) button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  text-align: inherit;
}
.dm button:focus-visible,
.dm input:focus-visible,
.dm textarea:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
.dm svg {
  width: 22px;
  height: 22px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.dm-icon {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: var(--sub) !important;
  flex: none;
}
.dm-icon:hover {
  background: var(--on) !important;
}

/* ---------- sidebar ---------- */
.dm-side {
  display: flex;
  flex-direction: column;
  width: min(380px, 38%);
  min-width: 280px;
  background: var(--side);
  border-inline-end: 1px solid var(--line);
}
.dm-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 58px;
  padding: 8px 12px;
  background: var(--panel);
}
.dm-me {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}
.dm-me b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-actions {
  display: flex;
}
.dm-search {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 8px 12px;
  padding: 0 12px;
  height: 36px;
  border-radius: 8px;
  background: var(--panel);
  color: var(--muted);
}
.dm-search svg {
  width: 18px;
  height: 18px;
}
.dm-search input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  color: var(--text);
  font: inherit;
}
.dm-tabs {
  display: flex;
  gap: 6px;
  padding: 0 12px 8px;
  border-bottom: 1px solid var(--line);
}
.dm-tabs button {
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--panel) !important;
  color: var(--sub) !important;
  font-size: 13.5px;
}
.dm-tabs button[aria-selected="true"] {
  background: color-mix(in srgb, var(--accent) 18%, transparent) !important;
  color: var(--accent) !important;
  font-weight: 600;
}
.dm-tabs button[data-count]:not([data-count=""])::after {
  content: attr(data-count);
  margin-inline-start: 6px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--badge);
  color: var(--accent-fg);
  font-size: 11.5px;
}
.dm-list,
.dm-picks {
  flex: 1;
  overflow-y: auto;
}
.dm-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 9px 14px;
  border-bottom: 1px solid var(--line) !important;
}
.dm-row:hover {
  background: var(--hover) !important;
}
.dm-row.dm-on {
  background: var(--on) !important;
}
.dm-row-main {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}
.dm-row-top,
.dm-row-sub {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.dm-row-top b {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
  font-size: 15.5px;
}
.dm-row-top time {
  font-size: 12px;
  color: var(--muted);
}
.dm-row-top time.dm-hot {
  color: var(--badge);
}
.dm-row-sub {
  color: var(--muted);
  font-size: 13.5px;
}
.dm-preview {
  display: flex;
  align-items: center;
  gap: 3px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-preview em {
  color: var(--badge);
  font-style: normal;
}
.dm-flag svg {
  width: 15px;
  height: 15px;
}
.dm-badge {
  min-width: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--badge);
  color: var(--accent-fg);
  font-size: 12px;
  font-weight: 600;
  text-align: center;
}
.dm-badge.dm-quiet {
  background: var(--muted);
}
.dm-row-menu {
  position: absolute;
  inset-inline-end: 10px;
  bottom: 8px;
  display: none;
  color: var(--muted);
  background: var(--hover);
  border-radius: 50%;
}
.dm-row:hover .dm-row-menu {
  display: block;
}
.dm-row-menu svg {
  width: 20px;
  height: 20px;
}
.dm-archived-row {
  color: var(--accent);
  font-weight: 500;
}
.dm-archived-row .dm-count {
  margin-inline-start: auto;
  color: var(--muted);
}
.dm-section {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 14px 16px 6px;
  color: var(--accent);
  font-size: 13px;
  font-weight: 600;
}
.dm-section span {
  color: var(--muted);
  font-weight: 400;
}
.dm-section svg {
  width: 17px;
  height: 17px;
}
.dm-section.dm-read svg {
  color: var(--read);
}
.dm-none {
  margin: 0;
  padding: 24px 18px;
  color: var(--muted);
  text-align: center;
}
.dm-error {
  color: var(--danger);
}
.dm-hit .dm-row-top b {
  font-size: 14px;
}

/* avatars */
.dm-av {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  overflow: hidden;
  flex: none;
  background: hsl(var(--h, 180) 45% 46%);
  color: #fff;
  font-size: 16px;
}
.dm-av img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.dm-av svg {
  width: 60%;
  height: 60%;
}
.dm-av.dm-sm {
  width: 38px;
  height: 38px;
  font-size: 14px;
}
.dm-av.dm-xs {
  width: 26px;
  height: 26px;
  font-size: 11px;
}
.dm-av.dm-lg {
  width: 120px;
  height: 120px;
  font-size: 40px;
}
.dm-av.dm-add {
  background: var(--accent);
  color: var(--accent-fg);
}
.dm-online {
  position: absolute;
  inset-inline-start: 48px;
  top: 42px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #25c16f;
  border: 2px solid var(--side);
}

/* ---------- conversation ---------- */
.dm-main {
  position: relative;
  display: flex;
  flex: 1;
  min-width: 0;
  background: var(--chat);
}
.dm-welcome {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  gap: 8px;
  padding: 32px;
  text-align: center;
  color: var(--sub);
  background: var(--panel);
  border-bottom: 6px solid var(--accent);
}
.dm-welcome-art svg {
  width: 84px;
  height: 84px;
  color: var(--accent);
  stroke-width: 1.2;
}
.dm-welcome h2 {
  margin: 8px 0 0;
  color: var(--text);
  font-weight: 400;
  font-size: 28px;
}
.dm-welcome p {
  max-width: 420px;
  margin: 0;
}
.dm-chat {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}
.dm-chat.dm-drop::after {
  content: "";
  position: absolute;
  inset: 8px;
  border: 3px dashed var(--accent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  pointer-events: none;
}
.dm-head {
  border-inline-start: 1px solid var(--line);
}
.dm-back {
  display: none;
}
.dm-head-who {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 0;
}
.dm-head-who > span:last-child {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.dm-head-who b {
  font-weight: 500;
  font-size: 16px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-head-who small {
  color: var(--muted);
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-head-who em {
  color: var(--badge);
  font-style: normal;
}
.dm-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px 6% 16px;
}
.dm-more {
  display: block;
  width: fit-content;
  margin: 0 auto 10px;
  padding: 6px 14px;
  border-radius: 999px;
  background: var(--in) !important;
  color: var(--accent) !important;
  box-shadow: 0 1px 1px rgba(11, 20, 26, 0.1);
  font-size: 13px;
}
.dm-day,
.dm-sys,
.dm-unread-line {
  display: flex;
  justify-content: center;
  margin: 10px 0;
}
.dm-day span,
.dm-sys span {
  padding: 5px 12px;
  border-radius: 8px;
  background: var(--in);
  color: var(--sub);
  font-size: 12.5px;
  box-shadow: 0 1px 1px rgba(11, 20, 26, 0.1);
  text-align: center;
}
.dm-unread-line span {
  width: 100%;
  padding: 4px;
  background: color-mix(in srgb, var(--in) 70%, transparent);
  color: var(--sub);
  font-size: 12.5px;
  text-align: center;
}
.dm-msg {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin-top: 2px;
}
.dm-msg.dm-first {
  margin-top: 10px;
}
.dm-msg.dm-mine {
  align-items: flex-end;
}
.dm-bubble {
  position: relative;
  max-width: min(560px, 78%);
  padding: 6px 9px 8px;
  border-radius: 8px;
  background: var(--in);
  box-shadow: 0 1px 0.5px rgba(11, 20, 26, 0.13);
  overflow-wrap: anywhere;
}
.dm-mine .dm-bubble {
  background: var(--out);
}
.dm-first .dm-bubble {
  border-start-start-radius: 0;
}
.dm-mine.dm-first .dm-bubble {
  border-start-start-radius: 8px;
  border-start-end-radius: 0;
}
.dm-msg.dm-flash .dm-bubble {
  animation: dm-flash 1.5s;
}
@keyframes dm-flash {
  30% {
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 40%, transparent);
  }
}
.dm-who {
  display: block;
  margin-bottom: 2px;
  color: hsl(var(--h) 55% 40%);
  font-size: 13px;
  font-weight: 600;
}
.dm[data-theme="dark"] .dm-who {
  color: hsl(var(--h) 60% 68%);
}
.dm-text {
  white-space: normal;
}
.dm-text a {
  color: var(--read);
}
.dm-text code {
  padding: 0 4px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--text) 8%, transparent);
  font-family: ui-monospace, Consolas, monospace;
  font-size: 13px;
}
.dm-meta {
  float: inline-end;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin: 6px 0 -4px 10px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1;
}
.dm-meta i {
  font-style: normal;
}
.dm-tick svg {
  width: 16px;
  height: 16px;
}
.dm-tick.dm-read {
  color: var(--read);
}
.dm-tick.dm-failed {
  color: var(--danger) !important;
}
.dm-deleted {
  color: var(--muted);
}
.dm-fwd {
  display: block;
  color: var(--muted);
  font-style: italic;
}
.dm-msg-menu {
  position: absolute;
  top: 2px;
  inset-inline-end: 2px;
  display: none;
  padding: 1px !important;
  border-radius: 50%;
  background: inherit !important;
  color: var(--muted) !important;
}
.dm-bubble:hover .dm-msg-menu,
.dm-msg-menu:focus-visible {
  display: block;
}
.dm-msg-menu svg {
  width: 20px;
  height: 20px;
}
.dm-quote {
  display: flex;
  flex-direction: column;
  width: 100%;
  margin-bottom: 4px;
  padding: 5px 8px;
  border-inline-start: 4px solid var(--accent) !important;
  border-radius: 6px;
  background: color-mix(in srgb, var(--text) 6%, transparent) !important;
  font-size: 13px;
}
.dm-quote b {
  color: var(--accent);
  font-weight: 600;
}
.dm-quote span {
  color: var(--sub);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-img {
  position: relative;
  display: block;
  width: min(320px, 60vw);
  aspect-ratio: 1 / var(--ratio, 0.75);
  margin: -2px -5px 4px;
  overflow: hidden;
  border-radius: 6px;
  background: color-mix(in srgb, var(--text) 8%, transparent) !important;
}
.dm-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.dm-voice {
  display: flex;
  align-items: center;
  gap: 8px;
  width: min(300px, 62vw);
  padding: 2px 0 4px;
}
:where(.dm) .dm-voice-play {
  display: grid;
  flex: none;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-fg);
}
.dm-voice-play svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}
.dm-voice-seek {
  flex: 1;
  min-width: 0;
  accent-color: var(--accent);
}
.dm-voice-time {
  min-width: 34px;
  color: var(--muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
:where(.dm) .dm-voice-rate {
  padding: 2px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 10%, transparent);
  color: var(--sub);
  font-size: 11.5px;
  font-weight: 600;
}
.dm-file {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 220px;
  margin-bottom: 4px;
  padding: 10px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--text) 6%, transparent);
  color: inherit;
  text-decoration: none;
}
.dm-file > span {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}
.dm-file b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}
.dm-file small {
  color: var(--muted);
}
.dm-file svg {
  color: var(--accent);
}
.dm-reacts {
  margin: -6px 8px 0;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--in) !important;
  box-shadow: 0 1px 2px rgba(11, 20, 26, 0.2);
  font-size: 13px;
  position: relative;
}
.dm-jump {
  position: absolute;
  inset-inline-end: 18px;
  bottom: 76px;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--in) !important;
  color: var(--sub) !important;
  box-shadow: var(--shadow);
}
.dm-jump span:not(:empty) {
  position: absolute;
  top: -6px;
  inset-inline-end: -4px;
  min-width: 20px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--badge);
  color: var(--accent-fg);
  font-size: 11.5px;
}
.dm-replying {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 0;
  background: var(--panel);
}
.dm-replying > div {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  padding: 6px 10px;
  border-inline-start: 4px solid var(--accent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--text) 6%, transparent);
  font-size: 13px;
}
.dm-replying b {
  color: var(--accent);
}
.dm-replying span {
  color: var(--sub);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-readonly {
  padding: 16px;
  background: var(--panel);
  color: var(--muted);
  text-align: center;
}
.dm-compose {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  padding: 8px 10px;
  background: var(--panel);
}
.dm-compose textarea {
  flex: 1;
  min-height: 42px;
  max-height: 140px;
  padding: 10px 14px;
  border: 0;
  border-radius: 8px;
  outline: 0;
  resize: none;
  background: var(--bg);
  color: var(--text);
  font: inherit;
}
.dm-send {
  background: var(--accent) !important;
  color: var(--accent-fg) !important;
  width: 42px;
  height: 42px;
}
.dm-recording {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  height: 42px;
  padding: 0 12px;
  border-radius: 8px;
  background: var(--bg);
  color: var(--sub);
}
.dm-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--danger);
  animation: dm-blink 1s infinite;
}
.dm-rec-time {
  flex: 1;
  font-variant-numeric: tabular-nums;
}
@keyframes dm-blink {
  50% {
    opacity: 0.25;
  }
}

/* ---------- drawer, menus, viewer, toast ---------- */
.dm-drawer {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  width: min(400px, 100%);
  background: var(--bg);
  border-inline-start: 1px solid var(--line);
  box-shadow: var(--shadow);
}
.dm-drawer > .dm-bar b {
  font-weight: 500;
  font-size: 16px;
}
.dm-drawer-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.dm-drawer .dm-search {
  flex: none;
}
.dm-field {
  flex: none;
  margin: 10px 12px 0;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  font: inherit;
  resize: vertical;
}
.dm-title-edit {
  margin: 10px 0 0;
  text-align: center;
  font-size: 18px;
  width: 100%;
}
.dm-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 12px;
}
.dm-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px 3px 10px;
  border-radius: 999px;
  background: var(--panel) !important;
  font-size: 13px;
}
.dm-chip svg {
  width: 14px;
  height: 14px;
}
.dm-check {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 2px solid var(--muted);
  border-radius: 4px;
}
.dm-on .dm-check {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-fg);
}
.dm-check svg {
  width: 16px;
  height: 16px;
}
.dm-primary {
  margin: 12px;
  padding: 11px;
  border-radius: 999px;
  background: var(--accent) !important;
  color: var(--accent-fg) !important;
  font-weight: 600;
  text-align: center !important;
}
.dm-av-edit {
  position: relative;
  display: inline-grid;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: none;
  cursor: pointer;
}
.dm-av-cam {
  position: absolute;
  right: 2px;
  bottom: 2px;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid var(--bg, #fff);
  background: var(--accent);
  color: var(--accent-fg);
}
.dm-av-cam svg {
  width: 18px;
  height: 18px;
}
.dm-text-btn {
  border: 0;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}
.dm-profile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 24px 16px 16px;
  border-bottom: 8px solid var(--panel);
  text-align: center;
}
.dm-profile h3 {
  margin: 10px 0 0;
  font-weight: 400;
  font-size: 22px;
}
.dm-profile p {
  margin: 0;
  color: var(--muted);
}
.dm-desc {
  margin: 0;
  padding: 12px 16px;
  color: var(--sub);
}
.dm-facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 6px 14px;
  margin: 0;
  padding: 16px;
}
.dm-facts dt {
  color: var(--muted);
}
.dm-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.dm-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px 0;
  color: var(--sub);
}
.dm-tag {
  padding: 0 6px;
  border: 1px solid var(--accent);
  border-radius: 4px;
  color: var(--accent);
  font-size: 11.5px;
}
.dm-member {
  cursor: default;
}
.dm-info-actions {
  display: flex;
  flex-direction: column;
  margin-top: 8px;
  border-top: 8px solid var(--panel);
}
.dm-info-actions button,
.dm-pop > button {
  display: block;
  width: 100%;
  padding: 12px 18px;
}
.dm-info-actions button:hover,
.dm-pop > button:hover {
  background: var(--hover) !important;
}
.dm-danger {
  color: var(--danger) !important;
}
.dm-pop {
  position: absolute;
  z-index: 8;
  min-width: 200px;
  max-width: 320px;
  padding: 6px 0;
  border-radius: 10px;
  background: var(--bg);
  box-shadow: var(--shadow);
}
.dm-pop > button {
  padding: 9px 18px;
}
.dm-pop-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px;
}
.dm-pop-row span {
  flex: 1;
}
.dm-quick {
  display: flex;
  justify-content: space-between;
  gap: 2px;
  padding: 4px 8px 8px;
  border-bottom: 1px solid var(--line);
}
.dm-quick button,
.dm-emoji button {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  font-size: 20px;
  text-align: center !important;
}
.dm-quick button:hover,
.dm-emoji button:hover,
.dm-quick button.dm-on {
  background: var(--on) !important;
}
.dm-emoji {
  display: grid;
  grid-template-columns: repeat(8, 34px);
  gap: 2px;
  padding: 4px 8px;
}
.dm-viewer {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  background: rgba(11, 20, 26, 0.96);
  color: #fff;
}
.dm-viewer header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
}
:where(.dm) .dm-viewer-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px 8px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  font-weight: 600;
}
.dm[dir="rtl"] .dm-viewer-back svg {
  transform: scaleX(-1);
}
.dm-viewer-back svg,
.dm-viewer-save svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
.dm-viewer-name {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}
.dm-viewer-name small {
  overflow: hidden;
  color: #aebac1;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-viewer .dm-viewer-save {
  color: #fff !important;
}
.dm-viewer-stage {
  display: grid;
  flex: 1;
  min-height: 0;
  place-items: center;
  padding: 8px 16px 16px;
}
.dm-viewer-stage img,
.dm-viewer-stage video {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}
.dm-video video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.dm-play {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.dm-play svg {
  width: 48px;
  height: 48px;
  padding: 12px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.5);
  fill: #fff;
}
.dm-find {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}
.dm-find input {
  flex: 1;
  min-width: 0;
  padding: 7px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  font: inherit;
  outline: none;
}
.dm-find-count {
  min-width: 56px;
  color: var(--muted);
  font-size: 12px;
  text-align: center;
}
.dm-msgs mark {
  border-radius: 3px;
  background: #fde68a;
  color: #111b21;
}
.dm-translated {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 2px;
  color: var(--muted);
  font-size: 11.5px;
  font-style: italic;
}
.dm-translated svg,
.dm-fwd svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
:where(.dm) .dm-translated button {
  padding: 0;
  color: var(--accent);
  font: inherit;
  font-style: normal;
}
.dm-fwd {
  display: flex;
  align-items: center;
  gap: 4px;
}
.dm-by-ai {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 2px;
  color: var(--accent);
  font-size: 11.5px;
  font-weight: 600;
}
.dm-by-ai svg,
.dm-av.dm-bot svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
.dm-av.dm-bot {
  background: var(--accent);
  color: var(--accent-fg);
}
.dm-av.dm-bot svg {
  width: 55%;
  height: 55%;
}
.dm-toast {
  position: absolute;
  bottom: 84px;
  left: 50%;
  z-index: 12;
  max-width: calc(100% - 32px);
  padding: 10px 16px;
  border-radius: 8px;
  background: #111b21;
  color: #fff;
  transform: translateX(-50%);
  box-shadow: var(--shadow);
}

/* ---------- phone width: one pane at a time ---------- */
.dm.dm-narrow .dm-side {
  width: 100%;
  min-width: 0;
  border: 0;
}
.dm.dm-narrow .dm-main {
  display: none;
}
.dm.dm-narrow.dm-chatting .dm-side {
  display: none;
}
.dm.dm-narrow.dm-chatting .dm-main {
  display: flex;
}
.dm.dm-narrow .dm-back {
  display: inline-grid;
}
.dm.dm-narrow .dm-scroll {
  padding: 8px 10px 12px;
}
.dm.dm-narrow .dm-bubble {
  max-width: 86%;
}
.dm.dm-narrow .dm-msg-menu {
  display: block;
  opacity: 0.6;
}
.dm.dm-narrow .dm-bubble {
  padding-inline-end: 26px;
}
[dir="rtl"] .dm-back svg {
  transform: scaleX(-1);
}
@media (max-width: 600px) {
  .dm {
    height: calc(100vh - 110px);
    border-radius: 0;
  }
}

/* ---------- calls ---------- */
.dm-sys-call button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 8px;
  background: var(--in);
  color: var(--sub);
  font-size: 12.5px;
  box-shadow: 0 1px 1px rgba(11, 20, 26, 0.1);
}
.dm-sys-call button span {
  padding: 0;
  background: none;
  box-shadow: none;
}
.dm-sys-call svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
.dm-sys-call time {
  color: var(--muted);
  font-size: 11px;
}
.dm-sys-call.dm-missed button,
.dm-call-row.dm-missed b {
  color: var(--danger);
}
.dm-call-row {
  cursor: pointer;
}
.dm-call-dir {
  margin-inline-end: 4px;
  font-style: normal;
}
.dm-call-row.dm-missed .dm-call-dir {
  color: var(--danger);
}
:where(.dm) .dm-netbar {
  padding: 6px 14px;
  font-size: 12.5px;
  color: var(--muted);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}
:where(.dm) .dm-netbar.dm-offline {
  color: #92400e;
  background: #fef3c7;
}
:where(.dm) .dm-pinbar {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 7px 14px;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: var(--in);
  color: var(--text);
  text-align: start;
  cursor: pointer;
  font: inherit;
}
:where(.dm) .dm-pinbar svg {
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--accent);
}
:where(.dm) .dm-pinbar span {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
:where(.dm) .dm-pinbar b {
  font-size: 12px;
  color: var(--accent);
}
:where(.dm) .dm-pinbar small {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13.5px;
  color: var(--text);
}
:where(.dm) .dm-mentions {
  display: flex;
  flex-direction: column;
  margin: 6px 12px 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--in);
  overflow: hidden;
}
:where(.dm) .dm-mentions button {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 10px;
  border: 0;
  background: transparent;
  color: var(--text);
  text-align: start;
  cursor: pointer;
  font: inherit;
}
:where(.dm) .dm-mentions button:hover,
:where(.dm) .dm-mentions button.dm-on {
  background: var(--hover);
}
:where(.dm) .dm-mentions .dm-av {
  width: 28px;
  height: 28px;
  font-size: 11px;
}
.dm-mention {
  color: var(--accent);
  font-weight: 700;
}
.dm-mention.dm-me {
  background: rgba(245, 158, 11, 0.22);
  border-radius: 4px;
  padding: 0 2px;
}
.dm-msg.dm-mentioned:not(.dm-mine) .dm-bubble {
  background: color-mix(in srgb, #f59e0b 12%, var(--in));
}
.dm-badge.dm-at {
  background: var(--accent);
  margin-inline-end: 4px;
}
:where(.dm) .dm-callbar {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 14px;
  background: var(--accent);
  color: var(--accent-fg);
  font-size: 13.5px;
}
.dm-callbar svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
.dm-callbar span {
  flex: 1;
  text-align: start;
}
.dm-callbar b {
  padding: 3px 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.2);
}
/* The call window: a layer on the page itself (outside the block), above ERP. */
.dm.dm-call-layer {
  display: contents;
}
.dm-call {
  position: fixed;
  inset: 0;
  z-index: 2147483000;
  display: flex;
  flex-direction: column;
  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px) env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
  background: #0b141a;
  color: #e9edef;
  font: 14.5px/1.45 "Segoe UI", -apple-system, BlinkMacSystemFont, Inter, system-ui, Roboto, Tahoma, Arial, sans-serif;
}
.dm-call-top {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}
.dm-call-head {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}
.dm-call-head b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-call-head small {
  color: #aebac1;
  font-variant-numeric: tabular-nums;
}
.dm-call .dm-icon {
  color: #e9edef !important;
}
.dm-call-stage {
  position: relative;
  display: grid;
  flex: 1;
  min-height: 0;
  gap: 8px;
  padding: 0 12px;
  grid-template-columns: 1fr;
}
.dm-call-stage[data-count="2"],
.dm-call-stage[data-count="3"],
.dm-call-stage[data-count="4"] {
  grid-template-columns: repeat(2, 1fr);
}
.dm-call-stage[data-count="5"],
.dm-call-stage[data-count="6"],
.dm-call-stage[data-count="7"],
.dm-call-stage[data-count="8"],
.dm-call-stage[data-count="9"] {
  grid-template-columns: repeat(3, 1fr);
}
.dm-call-card {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-align: center;
}
.dm-call-card b {
  font-size: 22px;
  font-weight: 600;
}
.dm-call-card small {
  color: #aebac1;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
}
.dm-av.dm-xl {
  width: 112px;
  height: 112px;
  font-size: 38px;
}
.dm-call[data-mode="incoming"] .dm-call-card .dm-av,
.dm-call[data-mode="outgoing"] .dm-call-card .dm-av {
  animation: dm-call-pulse 2s infinite;
}
@keyframes dm-call-pulse {
  0% { box-shadow: 0 0 0 0 rgba(45, 212, 191, 0.45); }
  70% { box-shadow: 0 0 0 22px rgba(45, 212, 191, 0); }
  100% { box-shadow: 0 0 0 0 rgba(45, 212, 191, 0); }
}
.dm-call-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  background: #000;
  opacity: 0.55;
}
.dm-tile {
  position: relative;
  display: grid;
  min-height: 0;
  place-items: center;
  overflow: hidden;
  border-radius: 12px;
  background: #1f2c33;
  outline: 3px solid transparent;
  transition: outline-color 0.15s;
}
.dm-tile.dm-speaking {
  outline-color: #2dd4bf;
}
/* Call video always shows the whole picture (black bars where the shapes differ), like
   WhatsApp desktop: filling the tile cut off heads and chins and looked zoomed in. */
.dm-tile video {
  /* Pinned to the tile: as a grid item it grew to its own height and was cut off. */
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  object-fit: contain;
  background: #000;
}
/* Your own corner picture is already your camera's shape (--ar), so it fills exactly. */
.dm-call-stage[data-count="1"] .dm-tile-me video:not(.dm-contain) {
  object-fit: cover;
}
.dm-mirror {
  transform: scaleX(-1);
}
.dm-tile-name {
  position: absolute;
  bottom: 8px;
  inset-inline-start: 8px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: calc(100% - 16px);
  padding: 2px 8px;
  overflow: hidden;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.5);
  font-size: 12.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dm-tile-name svg {
  width: 14px;
  height: 14px;
  flex: none;
  fill: none;
  stroke: #f2706a;
  stroke-width: 2;
}
/* One-to-one: the other person fills the screen, you are a small picture in the corner. */
.dm-call-stage[data-count="1"] .dm-tile-me {
  position: absolute;
  bottom: 12px;
  inset-inline-end: 24px;
  z-index: 2;
  width: min(28vw, 180px);
  aspect-ratio: var(--ar, 3 / 4);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.5);
}
/* A laptop webcam is wide: a wider corner picture keeps it a useful size. */
.dm-call-stage[data-count="1"] .dm-tile-me[data-shape="wide"] {
  width: min(32vw, 240px);
}
.dm-call-stage[data-count="1"] .dm-tile-me .dm-av.dm-xl {
  width: 56px;
  height: 56px;
  font-size: 20px;
}
.dm-call-note {
  margin: 8px auto 0;
  color: #fde68a;
  text-align: center;
}
.dm-call-note button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  background: #fde68a;
  color: #111b21;
  font-weight: 600;
}
.dm-call-note svg,
.dm-call-ctl svg {
  width: 24px;
  height: 24px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
.dm-call-controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 14px;
  padding: 18px 16px 22px;
}
:where(.dm) .dm-call-ctl {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  min-width: 64px;
  color: #e9edef;
  font-size: 12px;
}
.dm-call-ctl svg {
  box-sizing: content-box;
  padding: 16px;
  border-radius: 50%;
  background: #2a3942;
}
.dm-call-ctl.dm-off svg {
  background: #e9edef;
  color: #111b21;
}
.dm-call-ctl.dm-on svg,
.dm-call-ctl.dm-call-ok svg {
  background: #16a34a;
}
.dm-call-ctl.dm-call-end svg {
  background: #dc2626;
}
.dm-call-ctl:focus-visible svg {
  outline: 3px solid #2dd4bf;
  outline-offset: 2px;
}
.dm-call.dm-call-over .dm-call-top,
.dm-call[data-mode="incoming"] .dm-call-head,
.dm-call[data-mode="outgoing"] .dm-call-head {
  visibility: hidden;
}
.dm-call-pill {
  position: fixed;
  bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  inset-inline-end: calc(16px + env(safe-area-inset-right, 0px));
  z-index: 2147483000;
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: calc(100vw - 32px);
  padding: 10px 16px;
  border: 0;
  border-radius: 999px;
  background: #16a34a;
  color: #fff;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.35);
  font: 600 14px/1.2 "Segoe UI", system-ui, sans-serif;
  cursor: pointer;
}
.dm-call-pill .dm-dot {
  background: #fff;
}
@media (max-width: 600px) {
  .dm-call-controls {
    gap: 8px;
  }
  :where(.dm) .dm-call-ctl {
    min-width: 54px;
  }
  .dm-call-ctl span {
    display: none;
  }
  .dm-call-stage[data-count="2"],
  .dm-call-stage[data-count="3"],
  .dm-call-stage[data-count="4"] {
    grid-template-columns: 1fr;
  }
}
@media (prefers-reduced-motion: reduce) {
  .dm-call .dm-av {
    animation: none !important;
  }
}
